import React, { useState } from "react";
import {
  Box,
  Button,
  Divider,
  Grid,
  Paper,
  Typography,
  Link as MuiLink,
  Tooltip,
  Skeleton,
  Chip,
  Zoom,
  Collapse,
} from "@mui/material";
import { styled, keyframes } from "@mui/material/styles";
import KeyboardArrowDownIcon from "@mui/icons-material/KeyboardArrowDown";
import KeyboardArrowUpIcon from "@mui/icons-material/KeyboardArrowUp";
import PropTypes from "prop-types";

// Define a polished fade-in keyframe animation
const fadeIn = keyframes`
  from { 
    opacity: 0; 
    transform: translateY(10px); 
  }
  to { 
    opacity: 1; 
    transform: translateY(0); 
  }
`;

// Styled component for favorite item with improved hover effects
const FavoriteItem = styled(Box)(({ theme, imageurl }) => ({
  position: "relative",
  width: "100%",
  aspectRatio: "85 / 115",
  backgroundSize: "cover",
  backgroundPosition: "center",
  backgroundRepeat: "no-repeat",
  borderRadius: theme.shape.borderRadius * 1.5,
  backgroundImage: `url(${imageurl})`,
  cursor: "pointer",
  transition: "all 0.3s cubic-bezier(0.4, 0, 0.2, 1)",
  border: `1px solid ${theme.palette.divider}`,
  boxShadow: theme.shadows[1],
  "&::before": {
    content: '""',
    position: "absolute",
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    borderRadius: theme.shape.borderRadius * 1.5,
    background: "rgba(0, 0, 0, 0.05)",
    opacity: 0,
    transition: "opacity 0.3s ease",
  },
}));

// Enhanced tooltip for item info
const StyledTooltip = styled(({ className, ...props }) => (
  <Tooltip {...props} classes={{ popper: className }} />
))(({ theme }) => ({
  "& .MuiTooltip-tooltip": {
    backgroundColor: theme.palette.background.paper,
    color: theme.palette.text.primary,
    boxShadow: theme.shadows[3],
    fontSize: 12,
    padding: theme.spacing(1.5),
    maxWidth: 220,
    border: `1px solid ${theme.palette.divider}`,
  },
  "& .MuiTooltip-arrow": {
    color: theme.palette.background.paper,
  },
}));

/**
 * Component for displaying a single category of favorites with enhanced UI
 */
const FavoritesSection = ({ title, items, showMore, toggleShowMore, type }) => {
  const displayCount = showMore ? items.length : 8;
  const hasMore = items.length > 8;

  // Calculate item height (for smooth Collapse transition)

  return (
    <Paper
      elevation={0}
      sx={{
        mb: 3,
        p: 3,
        border: "1px solid",
        borderColor: (theme) => theme.palette.divider,
        borderRadius: 2,
        backgroundColor: (theme) => theme.palette.background.paper,
        position: "relative",
        overflow: "visible",
      }}
    >
      {/* Overlapping Category Title Chip */}
      <Chip
        label={title}
        color="primary"
        size="small"
        sx={{
          position: "absolute",
          top: -12,
          left: 16,
          fontWeight: 600,
          px: 1,
        }}
      />

      <Box sx={{ mt: 1.5 }}>
        <Collapse in={true} timeout={500}>
          <Grid container spacing={2}>
            {items.slice(0, displayCount).map((item, index) => {
              const imageUrl =
                item.coverImage?.large ||
                item.image?.large ||
                item.coverImage?.medium ||
                item.image?.medium ||
                "none";
              const itemTitle = item.title?.userPreferred || item.name?.full;
              const linkUrl = `https://anilist.co/${type.toLowerCase()}/${
                item.id
              }`;

              return (
                <Grid
                  item
                  xs={6}
                  sm={4}
                  md={3}
                  key={item.id}
                  sx={{
                    animation: `${fadeIn} 0.5s ease-out ${index * 0.05}s both`,
                  }}
                >
                  <MuiLink
                    href={linkUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    underline="none"
                    aria-label={itemTitle}
                  >
                    <StyledTooltip
                      title={
                        <Box>
                          <Typography variant="subtitle2" fontWeight={600}>
                            {itemTitle}
                          </Typography>
                          <Typography variant="caption" color="textSecondary">
                            {type} • ID: {item.id}
                          </Typography>
                        </Box>
                      }
                      placement="top"
                      arrow
                      TransitionComponent={Zoom}
                      enterDelay={400}
                    >
                      <FavoriteItem
                        imageurl={imageUrl}
                        aria-label={itemTitle}
                      />
                    </StyledTooltip>
                  </MuiLink>
                </Grid>
              );
            })}
          </Grid>
        </Collapse>
      </Box>

      {/* Show More/Less Button with icon */}
      {hasMore && (
        <Box
          sx={{
            position: "absolute",
            bottom: 0,
            right: 16,
            transform: "translateY(50%)",
            px: 1,
          }}
        >
          <Button
            variant="outlined"
            size="small"
            onClick={toggleShowMore}
            endIcon={
              showMore ? <KeyboardArrowUpIcon /> : <KeyboardArrowDownIcon />
            }
            sx={(theme) => ({
              fontSize: theme.typography.caption.fontSize,
              fontWeight: 600,
              py: 0.5,
              px: 1.5,
              borderRadius: 20,
              minWidth: "auto",
              backgroundColor: (theme) => theme.palette.background.paper,
            })}
          >
            {showMore ? "Show Less" : "Show More"}
          </Button>
        </Box>
      )}
    </Paper>
  );
};

/**
 * Main component to display all favorite categories
 */
const FavoritesDisplay = ({ favorites, loading = false }) => {
  const [showMore, setShowMore] = useState({
    anime: false,
    manga: false,
    characters: false,
    staff: false,
  });

  const toggleShowMore = (category) => {
    setShowMore((prevState) => ({
      ...prevState,
      [category]: !prevState[category],
    }));
  };

  if (loading) {
    return (
      <Grid container spacing={3}>
        <Grid item xs={12} md={6}>
          <Skeleton
            variant="rectangular"
            height={300}
            sx={{ borderRadius: 2, mb: 3 }}
          />
        </Grid>
        <Grid item xs={12} md={6}>
          <Skeleton
            variant="rectangular"
            height={300}
            sx={{ borderRadius: 2 }}
          />
        </Grid>
      </Grid>
    );
  }

  return (
    <Box
      sx={{
        width: "100%",
        display: "flex",
        flexDirection: "column",
        alignItems: "flex-start",
        animation: `${fadeIn} 0.6s ease-out`,
        px: 2,
        py: 1,
      }}
      aria-label="User favorites"
    >
    
      <Divider sx={{ mb: 2 }} />
      <Grid container spacing={3}>
        <Grid item xs={12} md={6}>
          {favorites.anime?.nodes.length > 0 && (
            <FavoritesSection
              title="Anime"
              items={favorites.anime.nodes}
              showMore={showMore.anime}
              toggleShowMore={() => toggleShowMore("anime")}
              type="anime"
            />
          )}
          {favorites.manga?.nodes.length > 0 && (
            <FavoritesSection
              title="Manga"
              items={favorites.manga.nodes}
              showMore={showMore.manga}
              toggleShowMore={() => toggleShowMore("manga")}
              type="manga"
            />
          )}
        </Grid>
        <Grid item xs={12} md={6}>
          {favorites.characters?.nodes.length > 0 && (
            <FavoritesSection
              title="Characters"
              items={favorites.characters.nodes}
              showMore={showMore.characters}
              toggleShowMore={() => toggleShowMore("characters")}
              type="character"
            />
          )}
          {favorites.staff?.nodes.length > 0 && (
            <FavoritesSection
              title="Staff"
              items={favorites.staff.nodes}
              showMore={showMore.staff}
              toggleShowMore={() => toggleShowMore("staff")}
              type="staff"
            />
          )}
        </Grid>
      </Grid>
    </Box>
  );
};

FavoritesSection.propTypes = {
  title: PropTypes.string.isRequired,
  items: PropTypes.array.isRequired,
  showMore: PropTypes.bool.isRequired,
  toggleShowMore: PropTypes.func.isRequired,
  type: PropTypes.string.isRequired,
};

FavoritesDisplay.propTypes = {
  favorites: PropTypes.shape({
    anime: PropTypes.shape({
      nodes: PropTypes.array.isRequired,
    }),
    manga: PropTypes.shape({
      nodes: PropTypes.array.isRequired,
    }),
    characters: PropTypes.shape({
      nodes: PropTypes.array.isRequired,
    }),
    staff: PropTypes.shape({
      nodes: PropTypes.array.isRequired,
    }),
  }).isRequired,
  loading: PropTypes.bool,
};

export default FavoritesDisplay;
