// hooks/useMediaFilters.js
import { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import debounce from 'lodash.debounce';
import { useLocalStorage } from './useLocalStorage';

// Prevents unnecessary re-renders with stable filter state
export const useMediaFilters = (mediaList, itemsPerPage) => {
  const [selectedStatus, setSelectedStatus] = useLocalStorage("selectedStatus", "ALL");
  const [selectedGenre, setSelectedGenre] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [sortBy, setSortBy] = useState("title");
  const [searchTerm, setSearchTerm] = useState("");
  const [debouncedSearchTerm, setDebouncedSearchTerm] = useState("");
  
  // Create a more aggressive debounce for better performance
  const debouncedSetSearchTerm = useRef(
    debounce((value) => {
      setDebouncedSearchTerm(value);
    }, 800) // Increased debounce time for better performance
  ).current;

  // Cleanup debounced functions on unmount
  useEffect(() => {
    return () => {
      debouncedSetSearchTerm.cancel();
    };
  }, [debouncedSetSearchTerm]);

  // Reset pagination on filter changes
  useEffect(() => setCurrentPage(1), [selectedStatus, selectedGenre, debouncedSearchTerm, sortBy]);

  // Optimized search preprocessing - only run when mediaList changes
  const searchIndex = useMemo(() => {
    // Create a more efficient search index
    return mediaList.map(entry => {
      // Create a single lowercase string for faster searching
      const searchableText = [
        entry.media.title?.romaji || '',
        entry.media.title?.english || '',
        ...(entry.media.tags?.map(t => t.name || '') || []),
        ...(entry.media.genres || [])
      ].join(' ').toLowerCase();
      
      // Pre-compute genre matches for faster filtering
      const genreMatches = new Set(entry.media.genres?.map(g => g.toLowerCase()) || []);
      
      return {
        ...entry,
        searchableText,
        genreMatches,
        // Pre-compute status match for faster filtering
        statusMatch: entry.status === selectedStatus || selectedStatus === "ALL"
      };
    });
  }, [mediaList, selectedStatus]);

  // Optimized filter functions with early returns for better performance
  const filteredList = useMemo(() => {
    // Early return for empty list
    if (!searchIndex.length) return [];
    
    const normalizedSearch = debouncedSearchTerm.trim().toLowerCase();
    const lowerSelectedGenre = selectedGenre.toLowerCase();
    
    // Fast path for no filters
    if (selectedStatus === "ALL" && !selectedGenre && !normalizedSearch) {
      return searchIndex;
    }
    
    // Use a more efficient filtering approach
    return searchIndex.filter(entry => {
      // Status check - early return if no match
      if (!entry.statusMatch) {
        return false;
      }
      
      // Genre check - early return if no match
      if (selectedGenre && !entry.genreMatches.has(lowerSelectedGenre)) {
        return false;
      }
      
      // Search check - only if there's a search term
      if (normalizedSearch && !entry.searchableText.includes(normalizedSearch)) {
        return false;
      }
      
      return true;
    });
  }, [searchIndex, selectedGenre, debouncedSearchTerm]);

  // Memoized collator for sorting
  const collator = useMemo(() => new Intl.Collator(undefined, { 
    sensitivity: "base",
    numeric: true 
  }), []);

  // Optimized sorting with stable reference
  const sortedList = useMemo(() => {
    if (!filteredList.length) return [];
    
    // Create a stable sort function
    const sortFn = (a, b) => {
      switch(sortBy) {
        case "title": 
          return collator.compare(
            a.media.title.romaji || '', 
            b.media.title.romaji || ''
          );
        case "score":
          return (b.score || 0) - (a.score || 0);
        case "progress":
          return (b.progress || 0) - (a.progress || 0);
        default: return 0;
      }
    };
    
    // Use a more efficient sorting approach for large lists
    return [...filteredList].sort(sortFn);
  }, [filteredList, sortBy, collator]);

  // Pagination with bounds checking
  const paginatedItems = useMemo(() => {
    const start = (currentPage - 1) * itemsPerPage;
    return sortedList.slice(start, start + itemsPerPage);
  }, [sortedList, currentPage, itemsPerPage]);

  // Stable filter handlers with immediate UI feedback
  const handleSearchChange = useCallback((query) => {
    setSearchTerm(query); // Update the input value immediately
    debouncedSetSearchTerm(query); // Debounce the actual filtering
  }, [debouncedSetSearchTerm]);

  const handleStatusChange = useCallback(value => {
    setSelectedStatus(value);
  }, [setSelectedStatus]);

  const handleGenreChange = useCallback(value => {
    setSelectedGenre(value);
  }, []);

  const resetFilters = useCallback(() => {
    setSelectedStatus("ALL");
    setSelectedGenre("");
    setSortBy("title");
    setSearchTerm("");
    setDebouncedSearchTerm("");
    setCurrentPage(1);
  }, [setSelectedStatus]);

  return {
    filteredList,
    sortedList,
    paginatedItems,
    currentPage,
    searchTerm,
    selectedStatus,
    selectedGenre,
    sortBy,
    setCurrentPage,
    handleSearchChange,
    handleStatusChange,
    handleGenreChange,
    setSortBy,
    resetFilters
  };
};