import React, { useState, useEffect } from "react";
import {
  Box,
  Paper,
  Typography,
  useTheme,
  Divider,
  Container,
  Fade,
  Skeleton,
  alpha,
  Grid,
  ToggleButtonGroup,
  ToggleButton,
  CircularProgress,
  Alert,
  Tabs,
  Tab,
  Button,
} from "@mui/material";
import MovieIcon from "@mui/icons-material/Movie";
import MenuBookIcon from "@mui/icons-material/MenuBook";
import CalendarTodayIcon from "@mui/icons-material/CalendarToday";
import SectionNav from "../../../components/userpage/sectionNav.jsx";
import { DETAILED_STATS_QUERY, fetchFromAniList } from "../../../queries/queries.js";

// Import modular components
import WeeklyReport from "./statistics-modules/weeklyReport.jsx";
import QuickFacts from "./statistics-modules/quickFacts.jsx";
import Discovery from "./statistics-modules/discovery.jsx";
import MostConsumed from "./statistics-modules/mostConsumed.jsx";
import StatusDistribution from "./statistics-modules/statusDistribution.jsx";
import TagsModule from "./statistics-modules/tagsModule.jsx";

/**
 * Statistics component that displays user anime and manga statistics
 * Redesigned to be inspired by Last.fm's reports
 * 
 * @param {Object} userData - User information
 * @param {String} userId - User ID
 * @param {String} defaultMediaType - Default media type ('anime' or 'manga')
 */
const Statistics = ({ userData, userId, defaultMediaType = "anime" }) => {
  const theme = useTheme();
  const [mediaType, setMediaType] = useState(defaultMediaType);
  const [activeTab, setActiveTab] = useState(0);
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [activeSection, setActiveSection] = useState("overviewSection");

  // Shared paper styles to maintain consistency
  const paperStyles = {
    p: 3,
    borderRadius: 2,
    border: `1px solid ${alpha(theme.palette.divider, 0.1)}`,
    background: alpha(theme.palette.background.paper, 0.8),
    backdropFilter: "blur(8px)",
    transition: "all 0.3s ease",
  };

  // Skeleton loading styles
  const skeletonStyles = {
    borderRadius: 1,
    backgroundColor: alpha(theme.palette.text.primary, 0.05),
  };

  // Define sections for the SectionNav
  const sections = [
    { 
      id: "overviewSection", 
      label: "Overview",
      color: theme.palette.primary.main,
      description: "General statistics overview"
    },
    { 
      id: "weeklySection", 
      label: "Weekly Report",
      color: theme.palette.info.main,
      description: "Your weekly activity report"
    },
    { 
      id: "detailedSection", 
      label: "Detailed Stats",
      color: theme.palette.success.main,
      description: "Detailed statistics breakdown"
    },
  ];

  // Handle section change
  const handleSectionChange = (sectionId) => {
    setActiveSection(sectionId);
  };

  // Handle media type change
  const handleMediaTypeChange = (event, newMediaType) => {
    if (newMediaType !== null) {
      setMediaType(newMediaType);
    }
  };

  // Handle tab change
  const handleTabChange = (event, newValue) => {
    setActiveTab(newValue);
  };

  // Fetch detailed statistics
  useEffect(() => {
    const fetchStats = async () => {
      try {
        setLoading(true);
        const data = await fetchFromAniList(DETAILED_STATS_QUERY, { userId });
        setStats(data.User.statistics);
        setLoading(false);
      } catch (err) {
        console.error("Error fetching statistics:", err);
        setError(err.message);
        setLoading(false);
      }
    };

    if (userId) {
      fetchStats();
    }
  }, [userId]);

  // Generate colors for charts and visualizations
  const generateColors = (count) => {
    const colors = [];
    const colorSet = [
      theme.palette.primary.main,
      theme.palette.secondary.main,
      theme.palette.info.main,
      theme.palette.success.main,
      theme.palette.warning.main,
      theme.palette.error.main,
    ];

    for (let i = 0; i < count; i++) {
      const colorIndex = i % colorSet.length;
      colors.push(colorSet[colorIndex]);
    }

    return colors;
  };

  // Format time function for display
  const formatTime = (minutes) => {
    if (!minutes) return "0 min";
    
    if (minutes < 60) {
      return `${minutes} min`;
    }
    
    const hours = Math.floor(minutes / 60);
    const remainingMinutes = minutes % 60;
    
    if (hours < 24) {
      return `${hours}h ${remainingMinutes > 0 ? `${remainingMinutes}m` : ''}`;
    }
    
    const days = Math.floor(hours / 24);
    const remainingHours = hours % 24;
    
    return `${days}d ${remainingHours > 0 ? `${remainingHours}h` : ''}`;
  };

  // Loading skeleton
  const StatsSkeleton = () => (
    <Box>
      <Skeleton 
        variant="rectangular" 
        sx={{ ...skeletonStyles, height: 200, mb: 3 }} 
      />
      
      <Grid container spacing={2} sx={{ mb: 3 }}>
        {[1, 2, 3, 4].map((item) => (
          <Grid item xs={6} sm={3} key={item}>
            <Skeleton 
              variant="rectangular" 
              sx={{ ...skeletonStyles, height: 120 }} 
            />
          </Grid>
        ))}
      </Grid>
      
      <Skeleton 
        variant="rectangular" 
        sx={{ ...skeletonStyles, height: 250, mb: 3 }} 
      />
      
      <Skeleton 
        variant="rectangular" 
        sx={{ ...skeletonStyles, height: 300 }} 
      />
    </Box>
  );

  // Overview section with Last.fm-style layout
  const OverviewSection = () => {
    if (loading || !stats) return <StatsSkeleton />;
    
    return (
      <Box>
        {/* Quick Facts Section - Inspired by Last.fm */}
        <QuickFacts 
          stats={stats} 
          mediaType={mediaType} 
          paperStyles={paperStyles}
          formatTime={formatTime}
        />
        
        {/* Weekly Report Section - Inspired by Last.fm */}
        <WeeklyReport 
          userId={userId}
          mediaType={mediaType}
          paperStyles={paperStyles}
          formatTime={formatTime}
          generateColors={generateColors}
        />
        
        {/* Most Consumed Section - Inspired by Last.fm */}
        <MostConsumed 
          userId={userId}
          mediaType={mediaType}
          paperStyles={paperStyles}
          formatTime={formatTime}
        />
        
        {/* Status Distribution */}
        <StatusDistribution 
          stats={stats}
          mediaType={mediaType}
          paperStyles={paperStyles}
          generateColors={generateColors}
        />
        
        {/* Tag Cloud */}
        <TagsModule 
          stats={stats}
          mediaType={mediaType}
          paperStyles={paperStyles}
        />
      </Box>
    );
  };
  
  // Discovery section
  const DiscoverySection = () => {
    if (loading || !stats) return <StatsSkeleton />;
    
    return (
      <Box>
        <Typography variant="h5" sx={{ mb: 3, fontWeight: 600 }}>
          Discover New {mediaType === "anime" ? "Anime" : "Manga"}
        </Typography>
        
        <Discovery 
          userId={userId}
          mediaType={mediaType}
          paperStyles={paperStyles}
        />
        
        {/* Additional discovery components can be added here */}
      </Box>
    );
  };
  
  // Weekly Report section
  const WeeklyReportSection = () => {
    if (loading) return <StatsSkeleton />;
    
    return (
      <Box>
        <Typography 
          variant="h5" 
          sx={{ 
            mb: 3, 
            fontWeight: 600,
            display: 'flex',
            alignItems: 'center'
          }}
        >
          <CalendarTodayIcon sx={{ mr: 1, color: theme.palette.info.main }} />
          Weekly Activity Report
        </Typography>
        
        <WeeklyReport 
          userId={userId}
          mediaType={mediaType}
          paperStyles={paperStyles}
          formatTime={formatTime}
          generateColors={generateColors}
        />
        
        <MostConsumed 
          userId={userId}
          mediaType={mediaType}
          paperStyles={paperStyles}
          formatTime={formatTime}
        />
      </Box>
    );
  };
  
  // Detailed stats section
  const DetailedStatsSection = () => {
    if (loading || !stats) return <StatsSkeleton />;
    
    return (
      <Box>
        <Typography variant="h5" sx={{ mb: 3, fontWeight: 600 }}>
          Detailed Statistics
        </Typography>
        
        <StatusDistribution 
          stats={stats}
          mediaType={mediaType}
          paperStyles={paperStyles}
          generateColors={generateColors}
        />
        
        <TagsModule 
          stats={stats}
          mediaType={mediaType}
          paperStyles={paperStyles}
        />
        
        <QuickFacts 
          stats={stats} 
          mediaType={mediaType} 
          paperStyles={paperStyles}
          formatTime={formatTime}
        />
      </Box>
    );
  };
  
  // Render the appropriate section based on activeSection
  const renderSection = () => {
    switch (activeSection) {
      case "overviewSection":
        return <OverviewSection />;
      case "weeklySection":
        return <WeeklyReportSection />;
      case "detailedSection":
        return <DetailedStatsSection />;
      default:
        return <OverviewSection />;
    }
  };

  return (
    <Fade in={true} timeout={500}>
      <Box>
        <Paper
          elevation={0}
          sx={{
            ...paperStyles,
            mb: 3,
            display: "flex",
            flexDirection: "column",
          }}
        >
          <Box
            sx={{
              display: "flex",
              flexDirection: { xs: "column", sm: "row" },
              justifyContent: "space-between",
              alignItems: { xs: "flex-start", sm: "center" },
              mb: 2,
            }}
          >
            <Typography variant="h5" sx={{ fontWeight: 600 }}>
              {mediaType === "anime" ? "Anime" : "Manga"} Statistics
            </Typography>
          </Box>

          <Divider sx={{ mb: 3 }} />

          {error ? (
            <Alert severity="error" sx={{ mb: 3 }}>
              {error}
            </Alert>
          ) : null}

          <SectionNav
            sections={sections}
            activeSection={activeSection}
            onChange={handleSectionChange}
          />
          
          {loading ? (
            <Box sx={{ display: "flex", justifyContent: "center", p: 5 }}>
              <CircularProgress />
            </Box>
          ) : (
            renderSection()
          )}
        </Paper>
      </Box>
    </Fade>
  );
};

export default Statistics;
