import React, { useMemo, useState, useCallback } from "react";
import PropTypes from "prop-types";
import {
  Box,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Button,
  InputAdornment,
  IconButton,
  Tooltip,
  useMediaQuery,
  Grid,
  CircularProgress,
  Fade,
} from "@mui/material";
import { useThemeContext } from "../themeContext";
import SearchIcon from "@mui/icons-material/Search";
import ClearIcon from "@mui/icons-material/Clear";
import PersonIcon from "@mui/icons-material/Person";
import SortIcon from "@mui/icons-material/Sort";
import FilterListIcon from "@mui/icons-material/FilterList";

const STATUS_OPTIONS = [
  { value: "ALL", label: "All" },
  { value: "CURRENT", label: "Reading/Watching" },
  { value: "PLANNING", label: "Planning" },
  { value: "COMPLETED", label: "Finished" },
  { value: "DROPPED", label: "Dropped" },
  { value: "PAUSED", label: "Paused" },
  { value: "REPEATING", label: "Repeating" },
];

const SORT_OPTIONS = [
  { value: "title", label: "Title" },
  { value: "score", label: "Score" },
  { value: "progress", label: "Progress" },
];

const AniListFilter = ({
  username,
  searchTerm,
  selectedStatus,
  selectedGenre,
  sortBy,
  genresWithCount,
  onUsernameChange,
  onSearchChange,
  onStatusChange,
  onGenreChange,
  onSortChange,
  onResetFilters,
  compact,
  fixedUsername,
}) => {
  const { themeName, currentTheme } = useThemeContext();
  const isDark = themeName === "dark";
  const isMobile = useMediaQuery(currentTheme.breakpoints.down("sm"));
  
  // Local state for search input to prevent lag
  const [localSearchTerm, setLocalSearchTerm] = useState(searchTerm);
  const [isSearching, setIsSearching] = useState(false);

  const gridSpacing = compact ? 1 : 2;
  const inputSize = compact ? "small" : "medium";

  const contrastSx = isDark
    ? {
        "& .MuiInputLabel-root": { color: currentTheme.palette.text.primary },
        "& .MuiOutlinedInput-notchedOutline": {
          borderColor: currentTheme.palette.text.primary,
        },
        "&:hover .MuiOutlinedInput-notchedOutline": {
          borderColor: currentTheme.palette.primary.main,
        },
        "&.Mui-focused .MuiOutlinedInput-notchedOutline": {
          borderColor: currentTheme.palette.primary.main,
        },
        "& .MuiInputBase-input": { color: currentTheme.palette.text.primary },
        "& .MuiSvgIcon-root": { color: currentTheme.palette.text.primary },
      }
    : {};

  const genreOptions = useMemo(
    () => [
      { value: "", label: "All Genres" },
      ...genresWithCount
        .slice()
        .sort((a, b) => b.count - a.count)
        .map((item) => ({
          value: item.genre,
          label: compact ? item.genre : `${item.genre} (${item.count})`,
        })),
    ],
    [genresWithCount, compact]
  );

  const hasActiveFilters = useMemo(() => {
    return (
      selectedStatus !== "ALL" ||
      !!selectedGenre ||
      !!searchTerm ||
      sortBy !== "title"
    );
  }, [selectedStatus, selectedGenre, searchTerm, sortBy]);

  const handleClearUsername = () => onUsernameChange("");

  // Optimized search handlers
  const handleSearchInputChange = useCallback((e) => {
    const value = e.target.value;
    setLocalSearchTerm(value);
    setIsSearching(true);
    onSearchChange(value);
  }, [onSearchChange]);

  const handleClearSearch = useCallback(() => {
    setLocalSearchTerm("");
    onSearchChange("");
  }, [onSearchChange]);

  return (
    <Box sx={{ width: "100%", px: compact ? 0 : 2 }}>
      <Grid container spacing={gridSpacing}>
        <Grid item xs={12}>
          <Grid container spacing={gridSpacing}>
            {!fixedUsername && (
              <Grid item xs={12} sm={4}>
                <Tooltip 
                  title="Enter your AniList username"
                  placement="top"
                  TransitionComponent={Fade}
                  arrow
                >
                  <TextField
                    label="Username"
                    variant="outlined"
                    size={inputSize}
                    value={username}
                    onChange={(e) => onUsernameChange(e.target.value)}
                    fullWidth
                    sx={contrastSx}
                    InputProps={{
                      startAdornment: (
                        <InputAdornment position="start">
                          <PersonIcon fontSize={inputSize} />
                        </InputAdornment>
                      ),
                      endAdornment: username && (
                        <IconButton
                          size={inputSize}
                          onClick={handleClearUsername}
                          aria-label="Clear username"
                        >
                          <ClearIcon fontSize={inputSize} />
                        </IconButton>
                      ),
                    }}
                  />
                </Tooltip>
              </Grid>
            )}

            <Grid item xs={12} sm={fixedUsername ? 6 : 4}>
              <Tooltip 
                title="Search by title, tags, or genres"
                placement="top"
                TransitionComponent={Fade}
                arrow
              >
                <TextField
                  label="Search titles, tags..."
                  variant="outlined"
                  size={inputSize}
                  value={localSearchTerm}
                  onChange={handleSearchInputChange}
                  fullWidth
                  sx={contrastSx}
                  InputProps={{
                    startAdornment: (
                      <InputAdornment position="start">
                        <SearchIcon fontSize={inputSize} />
                      </InputAdornment>
                    ),
                    endAdornment: (
                      <Box sx={{ display: 'flex', alignItems: 'center' }}>
                        {isSearching && (
                          <CircularProgress size={20} sx={{ mr: 1 }} />
                        )}
                        {localSearchTerm && (
                          <IconButton
                            size={inputSize}
                            onClick={handleClearSearch}
                            aria-label="Clear search"
                          >
                            <ClearIcon fontSize={inputSize} />
                          </IconButton>
                        )}
                      </Box>
                    ),
                  }}
                />
              </Tooltip>
            </Grid>

            <Grid item xs={12} sm={fixedUsername ? 6 : 4}>
              <Tooltip 
                title="Filter by watching/reading status"
                placement="top"
                TransitionComponent={Fade}
                arrow
              >
                <FormControl
                  variant="outlined"
                  size={inputSize}
                  fullWidth
                  sx={contrastSx}
                >
                  <InputLabel>Status</InputLabel>
                  <Select
                    value={selectedStatus}
                    onChange={(e) => onStatusChange(e.target.value)}
                    label="Status"
                  >
                    {STATUS_OPTIONS.map((option) => (
                      <MenuItem key={option.value} value={option.value}>
                        {option.label}
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Tooltip>
            </Grid>
          </Grid>
        </Grid>

        {/* Second Row */}
        <Grid item xs={12}>
          <Grid container spacing={gridSpacing}>
            <Grid item xs={12} sm={4}>
              <Tooltip 
                title="Sort your list"
                placement="top"
                TransitionComponent={Fade}
                arrow
              >
                <FormControl
                  variant="outlined"
                  size={inputSize}
                  fullWidth
                  sx={contrastSx}
                >
                  <InputLabel>Sort By</InputLabel>
                  <Select
                    value={sortBy}
                    onChange={(e) => onSortChange(e.target.value)}
                    label="Sort By"
                    startAdornment={
                      <InputAdornment position="start">
                        <SortIcon fontSize={inputSize} />
                      </InputAdornment>
                    }
                  >
                    {SORT_OPTIONS.map((option) => (
                      <MenuItem key={option.value} value={option.value}>
                        {option.label}
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Tooltip>
            </Grid>

            <Grid item xs={12} sm={4}>
              <Tooltip 
                title="Filter by genre"
                placement="top"
                TransitionComponent={Fade}
                arrow
              >
                <FormControl
                  variant="outlined"
                  size={inputSize}
                  fullWidth
                  sx={contrastSx}
                >
                  <InputLabel>Genre</InputLabel>
                  <Select
                    value={selectedGenre}
                    onChange={(e) => onGenreChange(e.target.value)}
                    label="Genre"
                    startAdornment={
                      <InputAdornment position="start">
                        <FilterListIcon fontSize={inputSize} />
                      </InputAdornment>
                    }
                  >
                    {genreOptions.map((option) => (
                      <MenuItem key={option.value} value={option.value}>
                        {option.label}
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Tooltip>
            </Grid>

            <Grid item xs={12} sm={4}>
              <Tooltip
                title={hasActiveFilters ? "Clear all filters" : "No active filters"}
                placement="top"
                TransitionComponent={Fade}
                arrow
              >
                <span>
                  <Button
                    fullWidth
                    variant="contained"
                    color="primary"
                    onClick={onResetFilters}
                    disabled={!hasActiveFilters}
                    sx={{ 
                      height: 40,
                      transition: 'all 0.2s ease-in-out',
                      '&:hover': {
                        transform: hasActiveFilters ? 'translateY(-2px)' : 'none',
                        boxShadow: hasActiveFilters ? 2 : 0,
                      }
                    }}
                    aria-label="Reset filters"
                  >
                    Clear Filters
                  </Button>
                </span>
              </Tooltip>
            </Grid>
          </Grid>
        </Grid>
      </Grid>
    </Box>
  );
};

AniListFilter.propTypes = {
  username: PropTypes.string.isRequired,
  searchTerm: PropTypes.string.isRequired,
  selectedStatus: PropTypes.string.isRequired,
  selectedGenre: PropTypes.string.isRequired,
  sortBy: PropTypes.string.isRequired,
  genresWithCount: PropTypes.arrayOf(
    PropTypes.shape({
      genre: PropTypes.string.isRequired,
      count: PropTypes.number.isRequired,
    })
  ).isRequired,
  onUsernameChange: PropTypes.func.isRequired,
  onSearchChange: PropTypes.func.isRequired,
  onStatusChange: PropTypes.func.isRequired,
  onGenreChange: PropTypes.func.isRequired,
  onSortChange: PropTypes.func.isRequired,
  onResetFilters: PropTypes.func.isRequired,
  compact: PropTypes.bool,
  fixedUsername: PropTypes.bool,
};

AniListFilter.defaultProps = {
  compact: false,
  fixedUsername: false,
};

export default React.memo(AniListFilter);
