import React, { useState, useEffect } from "react";
import {
  Box,
  Typography,
  useTheme,
  Paper,
  styled,
  Tooltip,
  Fade,
  IconButton,
  Collapse,
  useMediaQuery,
  alpha,
  Zoom,
} from "@mui/material";
import ChevronRightIcon from "@mui/icons-material/ChevronRight";
import ChevronLeftIcon from "@mui/icons-material/ChevronLeft";
import PropTypes from "prop-types";
import { useLocation } from "react-router-dom";

// Utility function to calculate contrast ratio for accessibility
const getContrast = (hexColor) => {
  // Convert hex to RGB
  const r = parseInt(hexColor.slice(1, 3), 16);
  const g = parseInt(hexColor.slice(3, 5), 16);
  const b = parseInt(hexColor.slice(5, 7), 16);
  
  // Calculate relative luminance
  const luminance = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
  
  // Return either black or white based on contrast
  return luminance > 0.5 ? "#000000" : "#FFFFFF";
};

const NavContainer = styled(Paper)(({ theme, isCollapsed, isMobile }) => ({
  position: "fixed",
  right: isMobile ? 16 : 32,
  top: isMobile ? undefined : 120,
  bottom: isMobile ? 16 : undefined,
  maxHeight: isMobile ? "60vh" : "calc(100vh - 160px)",
  overflowY: "auto",
  overflowX: "hidden",
  background:
    theme.palette.mode === "dark"
      ? alpha(theme.palette.grey[900], 0.95)
      : alpha(theme.palette.background.paper, 0.97),
  backdropFilter: "blur(8px)",
  borderRadius: theme.shape.borderRadius * 2,
  transition: "all 0.3s cubic-bezier(0.4, 0, 0.2, 1)",
  zIndex: 1000,
  boxShadow: theme.shadows[6],
  width: isCollapsed ? 48 : 200,
  border: `1px solid ${theme.palette.divider}`,
  padding: isCollapsed ? theme.spacing(1, 0.5) : theme.spacing(2),
  "&:hover": {
    boxShadow: theme.shadows[8],
  },
  "&::-webkit-scrollbar": {
    width: 4,
  },
  "&::-webkit-scrollbar-track": {
    backgroundColor: "transparent",
  },
  "&::-webkit-scrollbar-thumb": {
    backgroundColor:
      theme.palette.mode === "dark"
        ? theme.palette.grey[700]
        : theme.palette.grey[400],
    borderRadius: 10,
  },
  [theme.breakpoints.down("sm")]: {
    right: 8,
    width: isCollapsed ? 40 : 160,
  },
}));

const ToggleButton = styled(IconButton)(({ theme, isMobile }) => ({
  position: "absolute",
  top: isMobile ? 8 : 12,
  left: isMobile ? 8 : "auto",
  right: isMobile ? "auto" : 8,
  padding: 4,
  backgroundColor: alpha(
    theme.palette.mode === "dark"
      ? theme.palette.grey[800]
      : theme.palette.grey[200],
    0.8
  ),
  "&:hover": {
    backgroundColor:
      theme.palette.mode === "dark"
        ? theme.palette.grey[700]
        : theme.palette.grey[300],
  },
  transition: "transform 0.2s ease, opacity 0.2s ease",
  "&:active": {
    transform: "scale(0.9)",
  },
}));

const SectionItem = styled(Box)(({ theme, active, isCollapsed }) => ({
  display: "flex",
  alignItems: "center",
  cursor: "pointer",
  padding: isCollapsed ? theme.spacing(1.2, 0.5) : theme.spacing(0.8, 1.2),
  borderRadius: theme.shape.borderRadius * 1.5,
  marginBottom: theme.spacing(1),
  transition: "all 0.25s cubic-bezier(0.4, 0, 0.2, 1)",
  backgroundColor: active
    ? alpha(theme.palette.primary.main, 0.9)
    : "transparent",
  transformOrigin: "right center",
  "&:hover": {
    backgroundColor: active
      ? alpha(theme.palette.primary.main, 0.9)
      : alpha(theme.palette.action.hover, 0.15), // Increased hover contrast
    transform: isCollapsed ? "scale(1.1)" : "translateX(-8px)",
  },
  "&:active": {
    transform: isCollapsed ? "scale(0.95)" : "translateX(-4px)",
  },
  justifyContent: isCollapsed ? "center" : "flex-start",
  width: isCollapsed ? "auto" : "100%",
}));

const NavIndicator = styled(Box)(({ theme, active, color, isCollapsed }) => ({
  width: isCollapsed ? 16 : 12,
  height: isCollapsed ? 16 : 12,
  borderRadius: "50%",
  marginRight: isCollapsed ? 0 : theme.spacing(1.5),
  transition: "all 0.25s ease",
  background: active ? color : "transparent",
  border: `2px solid ${color}`,
  position: "relative",
  "&::after": active
    ? {
        content: '""',
        position: "absolute",
        top: "50%",
        left: "50%",
        transform: "translate(-50%, -50%)",
        width: "40%",
        height: "40%",
        borderRadius: "50%",
        backgroundColor: getContrast(color), // Dynamic contrast
      }
    : {},
  [theme.breakpoints.down("sm")]: {
    width: isCollapsed ? 12 : 10,
    height: isCollapsed ? 12 : 10,
  },
}));

const SectionNav = ({
  sections = [],
  title = "Sections",
  activeSection: controlledActiveSection,
  onSectionChange,
  useObserver = true,
  observerThreshold = 0.5,
  paperProps = {},
}) => {
  const theme = useTheme();
  const location = useLocation();
  const isMobile = useMediaQuery(theme.breakpoints.down("md"));
  const isSmallScreen = useMediaQuery(theme.breakpoints.down("sm"));
  const [activeInternal, setActiveInternal] = useState("");
  const [visible, setVisible] = useState(false);
  const [isCollapsed, setIsCollapsed] = useState(isMobile);
  
  // Only show on overview page
  const isOverviewPage = location.pathname.includes("/user/overview");
  
  // Determine active section from props or internal state
  const activeSection =
    controlledActiveSection !== undefined
      ? controlledActiveSection
      : activeInternal;

  // Update collapse state when device size changes
  useEffect(() => {
    setIsCollapsed(isMobile);
  }, [isMobile]);

  // Initialize intersection observer for tracking sections in viewport
  useEffect(() => {
    if (!useObserver || !isOverviewPage) return;

    // Delay visibility to allow for smooth transitions
    const timer = setTimeout(() => setVisible(true), 300);

    const observer = new IntersectionObserver(
      (entries) => {
        const visibleEntries = entries.filter((e) => e.isIntersecting);
        if (visibleEntries.length) {
          // Sort entries by their position in the viewport
          visibleEntries.sort(
            (a, b) => a.boundingClientRect.top - b.boundingClientRect.top
          );
          const newActive = visibleEntries[0].target.id;
          setActiveInternal(newActive);
          if (onSectionChange) onSectionChange(newActive);
        }
      },
      { threshold: observerThreshold }
    );

    // Observe all section elements
    sections.forEach((section) => {
      const el = document.getElementById(section.id);
      if (el) observer.observe(el);
    });

    // Cleanup observer and timer on unmount
    return () => {
      observer.disconnect();
      clearTimeout(timer);
    };
  }, [sections, observerThreshold, useObserver, onSectionChange, isOverviewPage]);

  // Handle click on a section item
  const handleClick = (id) => {
    const el = document.getElementById(id);
    if (el) {
      // Scroll to the section with offset
      const yOffset = -80;
      const y = el.getBoundingClientRect().top + window.pageYOffset + yOffset;
      window.scrollTo({ top: y, behavior: "smooth" });
    }
    // Update active section if not using observer
    if (!useObserver) {
      setActiveInternal(id);
      if (onSectionChange) onSectionChange(id);
    }
  };

  // Toggle collapsed state
  const toggleCollapse = () => {
    setIsCollapsed(!isCollapsed);
  };

  // Generate title gradient
  const titleGradient =
    theme.palette.mode === "dark"
      ? `linear-gradient(45deg, ${theme.palette.primary.light}, ${theme.palette.secondary.light})`
      : `linear-gradient(45deg, ${theme.palette.primary.dark}, ${theme.palette.secondary.dark})`;

  // Don't render if not on overview page or on small screens
  if (!isOverviewPage || isSmallScreen) {
    return null;
  }

  return (
    <Zoom in={visible && isOverviewPage} timeout={300}>
      <NavContainer
        elevation={4}
        isCollapsed={isCollapsed}
        isMobile={isMobile}
        aria-label="Section navigation panel"
        role="navigation"
        {...paperProps}
      >
        <ToggleButton
          size="small"
          onClick={toggleCollapse}
          isMobile={isMobile}
          aria-label={isCollapsed ? "Expand navigation" : "Collapse navigation"}
          aria-expanded={!isCollapsed}
        >
          {isCollapsed ? (
            <ChevronLeftIcon fontSize="small" />
          ) : (
            <ChevronRightIcon fontSize="small" />
          )}
        </ToggleButton>

        <Collapse in={!isCollapsed} orientation="horizontal">
          <Box sx={{ display: "flex", justifyContent: "center", mb: 2, mt: 3 }}>
            <Typography
              variant="subtitle2"
              sx={{
                fontWeight: 600,
                background: titleGradient,
                WebkitBackgroundClip: "text",
                WebkitTextFillColor: "transparent",
              }}
            >
              {title}
            </Typography>
          </Box>
        </Collapse>

        <Box
          role="menu"
          aria-label="Section navigation menu"
          sx={{
            mt: isCollapsed ? 4 : 0, // Added top margin when collapsed for better spacing
            display: "flex",
            flexDirection: "column",
            alignItems: isCollapsed ? "center" : "flex-start",
          }}
        >
          {sections.map((section) => {
            const isActive = activeSection === section.id;
            const sectionColor = section.color || theme.palette.primary.main;
            const textColor = isActive 
              ? getContrast(sectionColor) 
              : theme.palette.text.secondary;
              
            return (
              <Tooltip
                key={section.id}
                title={
                  isCollapsed
                    ? section.label
                    : section.description || section.label
                }
                arrow
                placement="left"
                enterDelay={isMobile ? 0 : 300}
                enterTouchDelay={50}
                disableInteractive
              >
                <SectionItem
                  onClick={() => handleClick(section.id)}
                  role="menuitem"
                  active={isActive}
                  isCollapsed={isCollapsed}
                  aria-pressed={isActive}
                  aria-current={isActive ? "location" : undefined}
                >
                  <NavIndicator
                    active={isActive}
                    color={sectionColor}
                    isCollapsed={isCollapsed}
                    aria-hidden="true"
                  />

                  <Collapse in={!isCollapsed} orientation="horizontal">
                    <Typography
                      variant="body2"
                      sx={{
                        fontWeight: isActive ? 600 : 500,
                        color: isActive
                          ? textColor
                          : theme.palette.text.secondary,
                        whiteSpace: "nowrap",
                        overflow: "hidden",
                        textOverflow: "ellipsis",
                        maxWidth: isMobile ? 120 : 140,
                      }}
                    >
                      {section.label}
                    </Typography>
                  </Collapse>
                </SectionItem>
              </Tooltip>
            );
          })}
        </Box>
      </NavContainer>
    </Zoom>
  );
};

SectionNav.propTypes = {
  sections: PropTypes.arrayOf(
    PropTypes.shape({
      id: PropTypes.string.isRequired,
      label: PropTypes.string.isRequired,
      color: PropTypes.string,
      description: PropTypes.string,
    })
  ),
  title: PropTypes.string,
  activeSection: PropTypes.string,
  onSectionChange: PropTypes.func,
  useObserver: PropTypes.bool,
  observerThreshold: PropTypes.number,
  paperProps: PropTypes.object,
};

export default SectionNav;