import React from "react";
import { BrowserRouter as Router, Route, Routes, useRoutes } from "react-router-dom";
import { Container, ThemeProvider, CssBaseline, Box } from "@mui/material";

import ErrorBoundary from "./components/ErrorBoundary.jsx";
import Header from "./components/header.jsx";
import { CustomThemeProvider, useThemeContext } from "./components/themeContext.jsx";
import ScrollToTopButton from "./components/ScrollToTopButton.jsx";
import { routes } from "./routes";

const AppContent = () => {
  const { currentTheme } = useThemeContext();
  const element = useRoutes(routes);

  return (
    <ThemeProvider theme={currentTheme}>
      <CssBaseline />
      <Box sx={{ display: 'flex', flexDirection: 'column', minHeight: '100vh' }}>
        <Header />
        <Box
          component="main"
          sx={{
            flexGrow: 1,
            pt: { xs: '64px', sm: '64px' }, // Account for fixed header
            pb: 3,
            width: '100%',
          }}
        >
          <ErrorBoundary>
            <Container maxWidth="xl" sx={{ height: '100%' }}>
              {element}
            </Container>
          </ErrorBoundary>
        </Box>
        <ScrollToTopButton />
      </Box>
    </ThemeProvider>
  );
};

function App() {
  return (
    <CustomThemeProvider>
      <Router basename="/tsubaki">
        <AppContent />
      </Router>
    </CustomThemeProvider>
  );
}

export default App;
