/**
 * GraphQL query to fetch user activity history
 */
export const ACTIVITY_HISTORY_QUERY = `
  query ($userId: Int, $page: Int) {
    Page(page: $page, perPage: 50) {
      activities(userId: $userId, sort: ID_DESC) {
        ... on ListActivity {
          id
          createdAt
          status
          progress
          media {
            id
            title {
              userPreferred
            }
            type
            format
          }
        }
        ... on TextActivity {
          id
          createdAt
          text
        }
        ... on MessageActivity {
          id
          createdAt
          message
          recipientId
        }
      }
      pageInfo {
        hasNextPage
        currentPage
        lastPage
      }
    }
  }
`;

