import React, { useState, useEffect, useCallback } from "react";
import { Fab, Zoom, useTheme } from "@mui/material";
import { KeyboardArrowUp as KeyboardArrowUpIcon } from "@mui/icons-material";

const ScrollToTopButton = ({ 
  threshold = 200,
  position = { bottom: 128, right: 128 },
  size = "medium",
  color = "primary",
  icon = <KeyboardArrowUpIcon />,
  zIndex = 1000,
  animationDuration = 300,
  ariaLabel = "scroll back to top"
}) => {
  const [visible, setVisible] = useState(false);
  const theme = useTheme();

  // Use throttling to improve scroll performance
  const checkScrollPosition = useCallback(() => {
    if (window.scrollY > threshold) {
      !visible && setVisible(true);
    } else {
      visible && setVisible(false);
    }
  }, [visible, threshold]);

  useEffect(() => {
    // Throttle scroll event for better performance
    let timeoutId;
    const throttledScrollHandler = () => {
      if (!timeoutId) {
        timeoutId = setTimeout(() => {
          checkScrollPosition();
          timeoutId = null;
        }, 100); // 100ms throttle
      }
    };

    window.addEventListener("scroll", throttledScrollHandler);
    
    // Check position on mount
    checkScrollPosition();
    
    return () => {
      window.removeEventListener("scroll", throttledScrollHandler);
      clearTimeout(timeoutId);
    };
  }, [checkScrollPosition]);

  const handleScrollToTop = () => {
    // Check if smooth scrolling is supported
    if ('scrollBehavior' in document.documentElement.style) {
      window.scrollTo({
        top: 0,
        behavior: "smooth"
      });
    } else {
      // Fallback for browsers that don't support smooth scrolling
      const scrollStep = -window.scrollY / (animationDuration / 15);
      const scrollInterval = setInterval(() => {
        if (window.scrollY !== 0) {
          window.scrollBy(0, scrollStep);
        } else {
          clearInterval(scrollInterval);
        }
      }, 15);
    }
  };

  return (
    <Zoom in={visible} timeout={300}>
      <Fab
        color={color}
        size={size}
        aria-label={ariaLabel}
        onClick={handleScrollToTop}
        onKeyPress={(e) => e.key === 'Enter' && handleScrollToTop()}
        tabIndex={visible ? 0 : -1}
        sx={{
          position: "fixed",
          ...position,
          zIndex,
          boxShadow: theme.shadows[4],
          '&:hover': {
            boxShadow: theme.shadows[6],
          },
          opacity: 0.9,
        
          transition: 'all 0.2s ease-in-out',
        }}
      >
        {icon}
      </Fab>
    </Zoom>
  );
};

export default ScrollToTopButton;