import React, { useState, useRef, useEffect } from "react";
import PropTypes from "prop-types";
import {
  Box,
  Typography,
  Avatar,
  ListItem,
  ListItemAvatar,
  Paper,
  Button,
  Collapse,
  IconButton,
  Chip,
  Tooltip,
  styled,
  Menu,
  MenuItem,
  Popover,
} from "@mui/material";
import Grow from "@mui/material/Grow";
import MuiLink from "@mui/material/Link";
import StarIcon from "@mui/icons-material/Star";
import MenuBookIcon from "@mui/icons-material/MenuBook";
import EventNoteIcon from "@mui/icons-material/EventNote";
import DescriptionIcon from "@mui/icons-material/Description";
import { 
  LocalOfferOutlined, 
  TagOutlined, 
  ExpandMore, 
  ExpandLess, 
  Info, 
  MoreVert, 
  DeleteOutline 
} from "@mui/icons-material";

// Styled components
const StyledPaper = styled(Paper)(({ theme, compact }) => ({
  marginBottom: compact ? theme.spacing(0.25) : theme.spacing(2),
  borderRadius: theme.spacing(0.5),
  transition: "background-color 0.3s ease",
  boxShadow: compact ? "none" : theme.shadows[1],
  border: `1px solid ${theme.palette.divider}`, // Added regular border
  "&:hover": {
    backgroundColor: theme.palette.action.hover,
  },
}));

const InfoContainer = styled(Box)(({ theme, compact }) => ({
  display: "flex",
  alignItems: "center",
  gap: theme.spacing(compact ? 0.3 : 0.75),
  marginBottom: theme.spacing(compact ? 0 : 0.5), // Reduced spacing for normal view
  "& .MuiSvgIcon-root": {
    fontSize: compact ? "0.9rem" : "1.2rem",
    color: theme.palette.text.secondary,
  },
}));

const StyledChip = styled(Chip)(({ theme, compact }) => ({
  margin: theme.spacing(0.25),
  height: compact ? 18 : 24,
  fontSize: compact ? "0.65rem" : "0.75rem",
  "&:hover": {
    backgroundColor: theme.palette.action.hover,
  },
}));

const ToggleButton = styled(Button)(({ theme }) => ({
  position: "relative",
  display: "flex",
  justifyContent: "center",
  alignItems: "center",
  textAlign: "center",
  textTransform: "none",
  fontSize: "0.875rem",
  fontWeight: theme.typography.fontWeightBold,
  borderRadius: theme.shape.borderRadius,
  transition: "background-color 0.3s ease",
  padding: theme.spacing(0.5, 0),
  minHeight: 0,
  border: "none",
  backgroundColor: "transparent",
  color: theme.palette.primary.main,
  "&:after": {
    content: '""',
    position: "absolute",
    bottom: 0,
    left: 0,
    right: 0,
    height: "2px",
    backgroundColor: theme.palette.primary.main,
    transform: "scaleX(0)",
    transition: "transform 0.3s ease",
  },
  "&:hover": {
    backgroundColor: "transparent",
    "&:after": { transform: "scaleX(1)" },
  },
  "&:focus": {
    backgroundColor: "transparent",
  },
}));

// Improved Cover Preview using MUI components
const CoverPreview = React.memo(({ coverImage, title }) => {
  return (
    <Box sx={{ p: 1 }}>
      <Avatar
        variant="rounded"
        src={coverImage || "default-cover.jpg"}
        alt={`Cover for ${title || "Untitled"}`}
        sx={{
          width: 180,
          height: 270,
          boxShadow: 1,
        }}
      />
    </Box>
  );
});

// Sub-components
const ScoreDisplay = React.memo(({ score, compact }) => (
  <InfoContainer compact={compact}>
    <StarIcon fontSize="inherit" />
    <Typography 
      variant={compact ? "caption" : "body2"} 
      color="text.secondary"
      sx={{ whiteSpace: "nowrap", fontWeight: compact ? 500 : 400 }}
    >
      {score || "N/A"}
    </Typography>
  </InfoContainer>
));

const ProgressDisplay = React.memo(({ progress = 0, chapters = null, compact }) => {
  const displayText = 
    !chapters || chapters === 0 ? `${progress}` :
    progress === chapters ? `${chapters}` :
    `${progress} / ${chapters}`;

  return (
    <InfoContainer compact={compact}>
      <MenuBookIcon fontSize="inherit" />
      <Typography 
        variant={compact ? "caption" : "body2"} 
        color="text.secondary"
        sx={{ whiteSpace: "nowrap", fontWeight: compact ? 500 : 400 }}
      >
        {displayText}
      </Typography>
    </InfoContainer>
  );
});

const DateDisplay = React.memo(({ startedAt, completedAt, formatDate, compact }) => {
  const renderDates = () => {
    if (!startedAt && !completedAt) return "N/A";
    const formattedStart = startedAt && formatDate(startedAt);
    const formattedEnd = completedAt && formatDate(completedAt);
    
    if (compact) {
      if (formattedEnd) return `${formattedEnd}`;
      if (formattedStart) return `${formattedStart}`;
      return "N/A";
    }
    
    if (formattedStart && formattedEnd) {
      return `${formattedStart} — ${formattedEnd}`;
    } else if (formattedStart) {
      return `Started ${formattedStart}`;
    } else if (formattedEnd) {
      return `Finished ${formattedEnd}`;
    }
    return "N/A";
  };

  const fullDateInfo = () => {
    if (!startedAt && !completedAt) return "No dates available";
    const formattedStart = startedAt && formatDate(startedAt);
    const formattedEnd = completedAt && formatDate(completedAt);
    
    if (formattedStart && formattedEnd) {
      return `Started: ${formattedStart}\nFinished: ${formattedEnd}`;
    } else if (formattedStart) {
      return `Started: ${formattedStart}`;
    } else if (formattedEnd) {
      return `Finished: ${formattedEnd}`;
    }
    return "No dates available";
  };

  return (
    <InfoContainer compact={compact}>
      <EventNoteIcon fontSize="inherit" />
      {compact ? (
        <Tooltip title={fullDateInfo()} arrow>
          <Typography 
            variant="caption" 
            color="text.secondary" 
            sx={{ 
              whiteSpace: "nowrap",
              maxWidth: "70px",
              overflow: "hidden",
              textOverflow: "ellipsis",
              fontWeight: 500
            }}
          >
            {renderDates()}
          </Typography>
        </Tooltip>
      ) : (
        <Typography variant="body2" color="text.secondary">
          {renderDates()}
        </Typography>
      )}
    </InfoContainer>
  );
});

const GenreDisplay = React.memo(({ genres, compact }) => {
  if (!Array.isArray(genres) || genres.length === 0) return null;
  
  const maxVisible = compact ? 1 : 5;
  const visibleGenres = genres.slice(0, maxVisible);
  const hasMore = genres.length > maxVisible;

  if (compact) {
    return (
      <InfoContainer compact={compact}>
        <LocalOfferOutlined fontSize="inherit" />
        <Box display="flex" alignItems="center" sx={{ maxWidth: "120px", overflow: "hidden" }}>
          <Typography variant="caption" color="text.secondary" noWrap sx={{ fontWeight: 500 }}>
            {visibleGenres.join(", ")}
            {hasMore ? " ..." : ""}
          </Typography>
          {hasMore && (
            <Tooltip title={genres.join(", ")} arrow>
              <Info sx={{ ml: 0.3, cursor: "help", fontSize: "0.7rem" }} />
            </Tooltip>
          )}
        </Box>
      </InfoContainer>
    );
  }

  const [expanded, setExpanded] = useState(false);
  const displayGenres = expanded ? genres : visibleGenres;

  return (
    <InfoContainer compact={compact}>
      <LocalOfferOutlined />
      <Box display="flex" flexWrap="wrap" gap={0.5} alignItems="center" flex={1}>
        {displayGenres.map((genre, index) => (
          <StyledChip key={index} label={genre} size="small" variant="outlined" compact={compact} />
        ))}
        {hasMore && (
          <IconButton size="small" onClick={() => setExpanded(!expanded)}>
            {expanded ? <ExpandLess /> : <ExpandMore />}
          </IconButton>
        )}
      </Box>
    </InfoContainer>
  );
});

const TagsDisplay = React.memo(({ tags, compact }) => {
  if (!Array.isArray(tags) || tags.length === 0) return null;
  
  if (compact) {
    const tagCount = tags.length;
    return (
      <InfoContainer compact={compact}>
        <TagOutlined fontSize="inherit" />
        <Tooltip title={tags.map(tag => `${tag.name} (${tag.rank}%)`).join(", ")} arrow>
          <Typography variant="caption" color="text.secondary" sx={{ fontWeight: 500 }}>
            {tagCount} {tagCount === 1 ? "tag" : "tags"}
          </Typography>
        </Tooltip>
      </InfoContainer>
    );
  }

  const [expanded, setExpanded] = useState(false);
  const maxVisible = 5;
  const initialTags = tags.slice(0, maxVisible);
  const additionalTags = tags.slice(maxVisible);

  return (
    <InfoContainer compact={compact}>
      <TagOutlined />
      <Box flex={1}>
        <Box
          display="flex"
          flexWrap="wrap"
          gap={0.5}
          alignItems="center"
          sx={{ minHeight: "2rem" }}
        >
          {initialTags.map((tag, index) => (
            <StyledChip
              key={index}
              label={`${tag.name} (${tag.rank}%)`}
              size="small"
              variant="outlined"
              compact={compact}
            />
          ))}
          {additionalTags.length > 0 && !expanded && (
            <IconButton size="small" onClick={() => setExpanded(true)}>
              <ExpandMore />
            </IconButton>
          )}
        </Box>
        <Collapse in={expanded} timeout="auto" unmountOnExit>
          <Box
            display="flex"
            flexWrap="wrap"
            gap={0.5}
            alignItems="center"
            mt={0.5}
          >
            {additionalTags.map((tag, index) => (
              <StyledChip
                key={`additional-${index}`}
                label={`${tag.name} (${tag.rank}%)`}
                size="small"
                variant="outlined"
                compact={compact}
              />
            ))}
            <IconButton size="small" onClick={() => setExpanded(false)}>
              <ExpandLess />
            </IconButton>
          </Box>
        </Collapse>
      </Box>
    </InfoContainer>
  );
});

const DescriptionDisplay = React.memo(({ description, compact }) => {
  if (compact) return null;

  const [show, setShow] = useState(false);
  const toggle = () => setShow((prev) => !prev);

  return (
    <InfoContainer sx={{ flexDirection: "column", alignItems: "flex-start" }} compact={compact}>
      <Box className="info-header" sx={{ display: "flex", alignItems: "center", gap: 1 }}>
        <DescriptionIcon />
        <ToggleButton onClick={toggle} variant="outlined" size="small">
          {show ? "Hide Description" : "Show Description"}
        </ToggleButton>
      </Box>
      <Collapse in={show} timeout="auto" unmountOnExit>
        <Typography variant="body2" color="text.secondary">
          {description || "No description available."}
        </Typography>
      </Collapse>
    </InfoContainer>
  );
});

const CompactMediaEntry = React.memo(({ entry, formatDate, progressKey }) => {
  const { media, score, progress } = entry;
  const total = media[progressKey] || 0;

  return (
    <Grow in timeout={300}>
      <StyledPaper
        aria-label={`Compact media entry for ${media.title.romaji}`}
        compact
        elevation={0}
        sx={{
          borderBottom: "1px solid",
          borderColor: "divider",
        }}
      >
        <ListItem
          divider={false}
          sx={{
            p: 1,
            gap: 1,
            alignItems: "center",
            width: "100%",
            display: "flex",
            flexDirection: "row",
            flexWrap: "nowrap",
          }}
          aria-label="Media entry container"
        >
          {/* Cover Image */}
          <Box
            sx={{
              minWidth: 48,
              width: 48,
              height: 72,
              mr: 1,
              position: "relative",
            }}
            aria-label="Media cover image"
          >
            <Avatar
              variant="rounded"
              src={media.coverImage?.large || "default-cover.jpg"}
              alt={`Cover for ${media.title?.romaji || "Untitled"}`}
              sx={{
                width: '100%',
                height: '100%',
                transition: "transform 0.2s ease",
                "&:hover": {
                  transform: "scale(1.05)",
                },
              }}
            />
          </Box>

          {/* Main Content */}
          <Box
            sx={{
              flex: 1,
              display: "flex",
              flexDirection: "column",
              gap: 0.5,
              minWidth: 0,
            }}
            aria-label="Media details"
          >
            {/* Title */}
            <Typography
              variant="body2"
              sx={{
                fontWeight: "bold",
                whiteSpace: "nowrap",
                overflow: "hidden",
                textOverflow: "ellipsis",
              }}
              aria-label="Media title"
            >
              {media.title.romaji}
            </Typography>

            {/* Metrics */}
            <Box
              sx={{
                display: "flex",
                flexWrap: "wrap",
                gap: 1,
                alignItems: "center",
              }}
              aria-label="Media metrics"
            >
              <ScoreDisplay score={score || 0} compact />
              <ProgressDisplay progress={progress || 0} chapters={total} compact />
              <DateDisplay
                startedAt={entry.startedAt}
                completedAt={entry.completedAt}
                formatDate={formatDate}
                compact
              />
              <GenreDisplay genres={media.genres} compact />
              <TagsDisplay tags={media.tags || []} compact />
            </Box>
          </Box>

          {/* Actions */}
          <Box
            sx={{
              display: "flex",
              alignItems: "center",
              ml: "auto",
            }}
            aria-label="Media actions"
          >
            <IconButton
              size="small"
              aria-label="More options"
              sx={{ p: 0.5 }}
            >
              <MoreVert fontSize="small" />
            </IconButton>
          </Box>
        </ListItem>
      </StyledPaper>
    </Grow>
  );
});

// Main component with improved responsive layout
const MediaEntry = React.memo(({ entry, formatDate, progressKey, compact, onDelete }) => {
  if (compact) {
    return <CompactMediaEntry entry={entry} formatDate={formatDate} progressKey={progressKey} />;
  }

  const { media, score, progress } = entry;
  const total = media[progressKey] || 0;
  const [menuAnchorEl, setMenuAnchorEl] = useState(null);
  
  // Menu handlers
  const handleMenuOpen = (event) => {
    event.stopPropagation();
    setMenuAnchorEl(event.currentTarget);
  };

  const handleMenuClose = () => {
    setMenuAnchorEl(null);
  };

  const handleDelete = (event) => {
    event.stopPropagation();
    if (onDelete) {
      onDelete(entry.id);
    }
    handleMenuClose();
  };

  return (
    <Grow in timeout={300}>
      <StyledPaper
        aria-label={`Media entry for ${media.title.romaji}`}
        compact={compact}
        elevation={0}
        sx={{
          borderBottom: "1px solid",
          borderColor: "divider",
        }}
      >
        <ListItem
          divider={false} // Removed divider since we're using a border on the StyledPaper
          sx={{
            p: compact ? "0.5rem 0.75rem" : 2,
            gap: compact ? 1 : 2,
            alignItems: "flex-start",
            width: "100%",
            // Removed fixed height settings to allow for dynamic sizing
            display: "flex",
            flexDirection: "row",
            flexWrap: "nowrap",
          }}
        >
          <ListItemAvatar
            sx={{
              mr: compact ? 1 : 2,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              borderRight: compact ? 1 : 2,
              borderColor: "divider",
              pr: compact ? 1 : 2,
              minWidth: compact ? "auto" : 56,
              alignSelf: compact ? "center" : "flex-start",
              // Removed fixed positioning
            }}
          >
            <Tooltip
              title={
                <CoverPreview
                  coverImage={media.coverImage?.large || "default-cover.jpg"}
                  title={media.title?.romaji || "Untitled"}
                />
              }
              placement="left"
              arrow
              PopperProps={{
                sx: {
                  "& .MuiTooltip-tooltip": {
                    backgroundColor: "background.paper",
                    color: "text.primary",
                    border: 1,
                    borderColor: "divider",
                    p: 0,
                    maxWidth: "none",
                  },
                },
              }}
              componentsProps={{
                tooltip: {
                  sx: { bgcolor: "background.paper" },
                },
              }}
              enterDelay={100}
              leaveDelay={200}
            >
              <Avatar
                variant="rounded"
                src={media.coverImage?.large || "default-cover.jpg"}
                alt={`Cover for ${media.title?.romaji || "Untitled"}`}
                sx={{
                  width: compact ? 32 : 100,
                  height: compact ? 48 : 150,
                  transition: "transform 0.2s ease, box-shadow 0.2s ease",
                  "&:hover": {
                    cursor: "pointer",
                  },
                }}
              />
            </Tooltip>
          </ListItemAvatar>

          <Box
            sx={{
              flex: 1,
              display: "flex",
              flexDirection: "column",
              alignItems: "flex-start",
              gap: compact ? 0.75 : 0.5, // Reduced gap for normal view
              overflow: "hidden", // Prevents content from overflowing
            }}
          >
            {/* Title section */}
            <Box
              sx={{
                width: "100%",
                mb: compact ? 0.5 : 0.75, // Reduced margin for normal view
              }}
            >
              <Typography
                variant={compact ? "body2" : "h6"}
                sx={{
                  lineHeight: compact ? 1.2 : 1.5,
                  fontWeight: "bold",
                  whiteSpace: compact ? "nowrap" : "normal",
                  overflow: compact ? "hidden" : "visible",
                  textOverflow: compact ? "ellipsis" : "clip",
                  maxWidth: compact ? "100%" : "none",
                  fontSize: compact ? "0.85rem" : undefined,
                }}
              >
                <MuiLink
                  href={media.siteUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                  underline="none"
                  sx={{
                    color: "inherit",
                    transition: "color 0.2s ease",
                    "&:hover": { color: "primary.main" },
                  }}
                >
                  {media.title.romaji}
                </MuiLink>
              </Typography>
              {media.title.english && !compact && (
                <Typography variant="subtitle2" color="text.secondary">
                  {media.title.english}
                </Typography>
              )}
            </Box>

            {/* Compact mode metrics section with entry actions */}
            {compact ? (
              <Box
                sx={{
                  display: "flex",
                  flexWrap: "wrap",
                  gap: 1.5,
                  width: "100%",
                  alignItems: "center",
                }}
              >
                <Box sx={{ display: "flex", gap: 1.5, flexWrap: "wrap" }}>
                  <ScoreDisplay score={score || 0} compact={compact} />
                  <ProgressDisplay progress={progress || 0} chapters={total} compact={compact} />
                  <DateDisplay
                    startedAt={entry.startedAt}
                    completedAt={entry.completedAt}
                    formatDate={formatDate}
                    compact={compact}
                  />
                  <GenreDisplay genres={media.genres} compact={compact} />
                  <TagsDisplay tags={media.tags || []} compact={compact} />
                </Box>

                {/* Action buttons - only in compact mode */}
                <Box
                  sx={{
                    display: "flex",
                    alignItems: "center",
                    ml: "auto",
                    mt: { xs: 0.5, sm: 0 },
                  }}
                >
                  <IconButton
                    size="small"
                    onClick={handleMenuOpen}
                    sx={{
                      padding: "3px",
                      marginRight: "4px",
                      "&:hover": {
                        backgroundColor: "rgba(0, 0, 0, 0.04)",
                      },
                    }}
                  >
                    <MoreVert fontSize="small" />
                  </IconButton>
                  <IconButton
                    size="small"
                    onClick={handleDelete}
                    sx={{
                      padding: "3px",
                      color: "error.light",
                      "&:hover": {
                        backgroundColor: "rgba(244, 67, 54, 0.04)",
                        color: "error.main",
                      },
                    }}
                  >
                    <DeleteOutline fontSize="small" />
                  </IconButton>

                  {/* Menu */}
                  <Menu
                    anchorEl={menuAnchorEl}
                    open={Boolean(menuAnchorEl)}
                    onClose={handleMenuClose}
                    PaperProps={{
                      elevation: 2,
                      sx: { minWidth: 120 },
                    }}
                  >
                    <MenuItem onClick={handleMenuClose}>Edit</MenuItem>
                    <MenuItem onClick={handleDelete} sx={{ color: "error.main" }}>
                      Delete
                    </MenuItem>
                  </Menu>
                </Box>
              </Box>
            ) : (
              /* Normal mode layout - with reduced spacing, no action buttons */
              <Box 
                sx={{ 
                  display: "flex", 
                  flexDirection: "column", 
                  gap: 0.5, // Reduced gap for normal view
                  width: "100%" 
                }}
              >
                {/* Score and Progress in one row */}
                <Box sx={{ display: "flex", gap: 2, mb: 0.5 }}> {/* Reduced margin */}
                  <ScoreDisplay score={score || 0} />
                  <ProgressDisplay progress={progress || 0} chapters={total} />
                </Box>
                
                {/* All other data with reduced spacing */}
                <DateDisplay
                  startedAt={entry.startedAt}
                  completedAt={entry.completedAt}
                  formatDate={formatDate}
                />
                <GenreDisplay genres={media.genres} />
                <TagsDisplay tags={media.tags || []} />
                <DescriptionDisplay description={media.description} />
                
                {/* No action buttons in normal view */}
              </Box>
            )}
          </Box>
        </ListItem>
      </StyledPaper>
    </Grow>
  );
});

MediaEntry.propTypes = {
  entry: PropTypes.object.isRequired,
  formatDate: PropTypes.func.isRequired,
  progressKey: PropTypes.string.isRequired,
  compact: PropTypes.bool,
  onDelete: PropTypes.func,
};

CoverPreview.propTypes = {
  coverImage: PropTypes.string,
  title: PropTypes.string,
};

ScoreDisplay.propTypes = {
  score: PropTypes.number,
  compact: PropTypes.bool,
};

ProgressDisplay.propTypes = {
  progress: PropTypes.number,
  chapters: PropTypes.number,
  compact: PropTypes.bool,
};

DateDisplay.propTypes = {
  startedAt: PropTypes.shape({
    year: PropTypes.number,
    month: PropTypes.number,
    day: PropTypes.number,
  }),
  completedAt: PropTypes.shape({
    year: PropTypes.number,
    month: PropTypes.number,
    day: PropTypes.number,
  }),
  formatDate: PropTypes.func.isRequired,
  compact: PropTypes.bool,
};

GenreDisplay.propTypes = {
  genres: PropTypes.arrayOf(PropTypes.string),
  compact: PropTypes.bool,
};

TagsDisplay.propTypes = {
  tags: PropTypes.arrayOf(
    PropTypes.shape({
      name: PropTypes.string.isRequired,
      rank: PropTypes.number.isRequired,
    })
  ),
  compact: PropTypes.bool,
};

DescriptionDisplay.propTypes = {
  description: PropTypes.string,
  compact: PropTypes.bool,
};

MediaEntry.defaultProps = {
  compact: false,
};

export default MediaEntry;