import React, { useState, useEffect, useMemo } from "react";
import {
  Box,
  Card,
  CardContent,
  Typography,
  Grid,
  alpha,
  useTheme,
  CircularProgress,
  Divider,
  Tooltip,
  Button
} from "@mui/material";
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip as RechartsTooltip, 
  ResponsiveContainer,
  Cell
} from "recharts";
import CalendarTodayIcon from "@mui/icons-material/CalendarToday";
import TrendingUpIcon from "@mui/icons-material/TrendingUp";
import { WEEKLY_ACTIVITY_QUERY, fetchFromAniList } from "../../../../queries/queries";
import { ACTIVITY_QUERY } from "../../../../queries/queries";

/**
 * Weekly Report component that shows anime/manga consumption for the past week
 * Inspired by Last.fm's weekly listening report
 */
const WeeklyReport = ({ userId, mediaType, paperStyles, formatTime, generateColors }) => {
  const theme = useTheme();
  const [weeklyData, setWeeklyData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  
  // Get the previous week's date range (Monday to Sunday)
  const getPreviousWeekRange = () => {
    const now = new Date();
    const lastMonday = new Date(now);
    lastMonday.setDate(now.getDate() - now.getDay() - 6);
    lastMonday.setHours(0, 0, 0, 0); // Start of day
    
    const lastSunday = new Date(lastMonday);
    lastSunday.setDate(lastMonday.getDate() + 6);
    lastSunday.setHours(23, 59, 59, 999); // End of day

    const range = {
      start: Math.floor(lastMonday.getTime() / 1000),
      end: Math.floor(lastSunday.getTime() / 1000),
      display: `${lastMonday.toLocaleDateString()} - ${lastSunday.toLocaleDateString()}`
    };

    console.log('Calculated date range:', {
      start: new Date(range.start * 1000).toISOString(),
      end: new Date(range.end * 1000).toISOString(),
      display: range.display
    });
    return range;
  };

  const validateQueryVariables = (variables) => {
    if (!variables.userId || isNaN(variables.userId)) {
      throw new Error('Invalid userId');
    }
    if (!['ANIME', 'MANGA'].includes(variables.type)) {
      throw new Error('Invalid media type');
    }
    if (!variables.startDate || !variables.endDate || variables.startDate > variables.endDate) {
      throw new Error('Invalid date range');
    }
  };

  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        setError(null);

        const { start, end } = getPreviousWeekRange();
        const queryVariables = {
          userId: parseInt(userId),
          type: mediaType.toUpperCase(),
          startDate: start,
          endDate: end,
          perPage: 100
        };

        // Validate query variables
        validateQueryVariables(queryVariables);

        console.log('Making API request with validated variables:', {
          ...queryVariables,
          startDate: new Date(queryVariables.startDate * 1000).toISOString(),
          endDate: new Date(queryVariables.endDate * 1000).toISOString()
        });

        const response = await fetchFromAniList(WEEKLY_ACTIVITY_QUERY, queryVariables);

        console.log('API response:', response);

        if (!response?.Page?.activities) {
          console.log('No activities found in response');
          setWeeklyData({ 
            hasActivity: false, 
            displayRange: getPreviousWeekRange().display,
            dailyActivity: Array(7).fill(0).map((_, i) => ({
              day: ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'][i],
              count: 0,
              time: 0
            }))
          });
          return;
        }

        const activities = response.Page.activities;
        console.log('Activities received:', activities);

        const dailyActivity = Array(7).fill(0).map((_, i) => ({
          day: ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'][i],
          count: 0,
          time: 0
        }));

        let totalCount = 0;
        let totalTime = 0;

        activities.forEach(activity => {
          if (!activity.media) return;

          const date = new Date(activity.createdAt * 1000);
          const dayIndex = date.getDay() === 0 ? 6 : date.getDay() - 1;
          const progress = activity.progress || 1;

          console.log(`Processing activity:`, {
            date: date.toISOString(),
            dayIndex,
            progress,
            media: activity.media.title.userPreferred
          });

          dailyActivity[dayIndex].count += progress;
          totalCount += progress;

          if (mediaType === "anime" && activity.media.duration) {
            const time = progress * activity.media.duration;
            dailyActivity[dayIndex].time += time;
            totalTime += time;
          }
        });

        console.log('Processed daily activity:', dailyActivity);

        setWeeklyData({
          hasActivity: totalCount > 0,
          dailyActivity,
          totalCount,
          totalTime,
          displayRange: getPreviousWeekRange().display
        });

      } catch (err) {
        console.error("Error fetching weekly data:", {
          message: err.message,
          stack: err.stack,
          response: err.response
        });
        setError(err.message);
        setWeeklyData({ 
          hasActivity: false,
          dailyActivity: Array(7).fill(0).map((_, i) => ({
            day: ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'][i],
            count: 0,
            time: 0
          }))
        });
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [userId, mediaType]);
  
  if (loading) {
    return (
      <Card sx={{ ...paperStyles, mb: 3 }}>
        <CardContent>
          <Box display="flex" justifyContent="center" p={3}>
            <CircularProgress />
          </Box>
        </CardContent>
      </Card>
    );
  }
  
  if (error) {
    return (
      <Card sx={{ ...paperStyles, mb: 3 }}>
        <CardContent>
          <Typography color="error">Error: {error}</Typography>
        </CardContent>
      </Card>
    );
  }
  
  if (!weeklyData) {
    return (
      <Card sx={{ ...paperStyles, mb: 3 }}>
        <CardContent>
          <Typography variant="h6">No weekly data available</Typography>
          <Typography variant="body2">
            We don't have enough data about your recent activity.
          </Typography>
        </CardContent>
      </Card>
    );
  }
  
  // Handle no activity case
  if (!weeklyData.hasActivity) {
    return (
      <Card sx={{ ...paperStyles, mb: 3 }}>
        <CardContent>
          <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
            <CalendarTodayIcon sx={{ color: theme.palette.primary.main, mr: 1 }} />
            <Typography variant="h6" sx={{ fontWeight: 600 }}>
              Your weekly {mediaType} report
            </Typography>
          </Box>
          
          <Typography variant="body2" color="text.secondary" sx={{ my: 2 }}>
            {weeklyData.displayRange}
          </Typography>
          
          <Box sx={{ 
            py: 4, 
            display: 'flex', 
            flexDirection: 'column', 
            alignItems: 'center',
            justifyContent: 'center' 
          }}>
            <Box sx={{ 
              width: 60, 
              height: 60, 
              borderRadius: '50%', 
              backgroundColor: alpha(theme.palette.text.secondary, 0.1),
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              mb: 2
            }}>
              <CalendarTodayIcon color="action" sx={{ fontSize: 30 }} />
            </Box>
            <Typography variant="h6" color="text.secondary">
              No activity during this week
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mt: 1, maxWidth: 400, textAlign: 'center' }}>
              You didn't {mediaType === "anime" ? "watch any anime" : "read any manga"} this week.
            </Typography>
          </Box>
        </CardContent>
      </Card>
    );
  }
  
  // Generate colors for charts
  const chartColors = generateColors(7);
  
  return (
    <Card 
      sx={{ 
        ...paperStyles, 
        mb: 3,
        overflow: 'hidden'
      }}
    >
      <CardContent>
        <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
          <CalendarTodayIcon sx={{ color: theme.palette.primary.main, mr: 1 }} />
          <Typography variant="h6" sx={{ fontWeight: 600 }}>
            Your weekly {mediaType} report
          </Typography>
        </Box>
        
        <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
          {weeklyData.displayRange}
        </Typography>
        
        {/* Weekly summary */}
        <Grid container spacing={3} sx={{ mb: 3 }}>
          <Grid item xs={12} sm={6} md={3}>
            <Box>
              <Typography variant="caption" color="text.secondary">
                {mediaType === "anime" ? "ANIME WATCHED" : "MANGA READ"}
              </Typography>
              <Typography variant="h4" sx={{ fontWeight: 'bold', my: 0.5 }}>
                {weeklyData.totalItems}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                {weeklyData.averagePerDay} per day on average
              </Typography>
            </Box>
          </Grid>
          
          <Grid item xs={12} sm={6} md={3}>
            <Box>
              <Typography variant="caption" color="text.secondary">
                {mediaType === "anime" ? "EPISODES WATCHED" : "CHAPTERS READ"}
              </Typography>
              <Typography variant="h4" sx={{ fontWeight: 'bold', my: 0.5 }}>
                {weeklyData.totalEpisodesOrChapters}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                across {weeklyData.totalItems} different {mediaType}
              </Typography>
            </Box>
          </Grid>
          
          <Grid item xs={12} sm={6} md={3}>
            <Box>
              <Typography variant="caption" color="text.secondary">
                {mediaType === "anime" ? "TIME WATCHED" : "VOLUME EQUIVALENT"}
              </Typography>
              <Typography variant="h4" sx={{ fontWeight: 'bold', my: 0.5 }}>
                {mediaType === "anime" 
                  ? formatTime(weeklyData.totalTimeSpent) 
                  : Math.round(weeklyData.totalEpisodesOrChapters / 5)}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                {mediaType === "anime" 
                  ? `${Math.round(weeklyData.totalTimeSpent / 60)} hours total` 
                  : "estimated volumes"}
              </Typography>
            </Box>
          </Grid>
          
          <Grid item xs={12} sm={6} md={3}>
            <Box>
              <Typography variant="caption" color="text.secondary">
                MOST ACTIVE DAY
              </Typography>
              <Typography variant="h4" sx={{ fontWeight: 'bold', my: 0.5 }}>
                {weeklyData.mostActive.day}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                {weeklyData.mostActive.count} {mediaType === "anime" ? "episodes" : "chapters"} ({weeklyData.mostActive.percentage}%)
              </Typography>
            </Box>
          </Grid>
        </Grid>
        
        <Divider sx={{ my: 2 }} />
        
        {/* Daily Activity Chart */}
        <Typography variant="subtitle1" sx={{ fontWeight: 600, mb: 2 }}>
          Daily Activity
        </Typography>
        
        <Box sx={{ height: 250, mb: 2 }}>
          <ResponsiveContainer width="100%" height="100%">
            <BarChart
              data={weeklyData.dailyActivity}
              margin={{ top: 10, right: 10, left: 0, bottom: 0 }}
            >
              <CartesianGrid strokeDasharray="3 3" vertical={false} />
              <XAxis 
                dataKey="day" 
                axisLine={false}
                tickLine={false}
              />
              <YAxis 
                axisLine={false}
                tickLine={false}
                tickFormatter={(value) => value}
              />
              <RechartsTooltip
                content={({ active, payload }) => {
                  if (active && payload && payload.length) {
                    const data = payload[0].payload;
                    return (
                      <Box sx={{ 
                        bgcolor: 'background.paper', 
                        p: 1.5, 
                        borderRadius: 1,
                        boxShadow: 3,
                        border: `1px solid ${alpha(theme.palette.grey[500], 0.2)}`
                      }}>
                        <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 0.5 }}>
                          {data.day}
                        </Typography>
                        <Typography variant="body2">
                          {mediaType === "anime" 
                            ? `${data.count} episodes watched` 
                            : `${data.count} chapters read`}
                        </Typography>
                        {mediaType === "anime" && data.time > 0 && (
                          <Typography variant="body2" color="text.secondary">
                            {formatTime(data.time)} of watch time
                          </Typography>
                        )}
                      </Box>
                    );
                  }
                  return null;
                }}
              />
              <Bar 
                dataKey="count" 
                radius={[4, 4, 0, 0]}
              >
                {weeklyData.dailyActivity.map((entry, index) => (
                  <Cell 
                    key={`cell-${index}`} 
                    fill={chartColors[index % chartColors.length]} 
                  />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </Box>
        
        {/* Top Genres */}
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mb: 2 }}>
          <Typography variant="body2" sx={{ fontWeight: 600, mr: 1 }}>
            Top Genres:
          </Typography>
          {weeklyData.topGenres.map((genre, index) => (
            <Tooltip 
              key={genre} 
              title={
                <React.Fragment>
                  <Typography variant="subtitle2" sx={{ mb: 0.5 }}>
                    {genre} was your #${index + 1} genre this week
                  </Typography>
                  <Typography variant="body2">
                    {mediaType === "anime" 
                      ? index === 0 
                        ? "Popular examples: Attack on Titan, Demon Slayer, My Hero Academia" 
                        : "You watched several titles in this genre this week"
                      : index === 0 
                        ? "Popular examples: One Piece, Berserk, Chainsaw Man" 
                        : "You read several titles in this genre this week"
                    }
                  </Typography>
                </React.Fragment>
              }
            >
              <Box 
                sx={{ 
                  px: 1.5, 
                  py: 0.5, 
                  borderRadius: 10, 
                  backgroundColor: alpha(chartColors[index], 0.15),
                  color: chartColors[index],
                  fontSize: '0.75rem',
                  fontWeight: 'bold'
                }}
              >
                {genre}
              </Box>
            </Tooltip>
          ))}
        </Box>
      </CardContent>
    </Card>
  );
};

export default WeeklyReport;
