import React, { useCallback } from "react";
import { Box, Button, TextField, Typography, useTheme } from "@mui/material";
import PropTypes from "prop-types";

const Pagination = ({ totalItems, itemsPerPage, currentPage, onPageChange }) => {
  const theme = useTheme();
  const isDark = theme.palette.mode === "dark";
  const totalPages = Math.ceil(totalItems / itemsPerPage) || 1;

  const handlePageChange = useCallback(
    (action) => {
      switch (action) {
        case "prev":
          if (currentPage > 1) onPageChange(currentPage - 1);
          break;
        case "next":
          if (currentPage < totalPages) onPageChange(currentPage + 1);
          break;
        default:
          break;
      }
    },
    [currentPage, totalPages, onPageChange]
  );

  const handleCustomPageChange = useCallback(
    (e) => {
      const page = parseInt(e.target.value, 10) || 1;
      const validatedPage = Math.min(Math.max(page, 1), totalPages);
      onPageChange(validatedPage);
    },
    [totalPages, onPageChange]
  );

  if (totalItems <= itemsPerPage) return null;

  // Styling for buttons: in dark mode we set border and text colors,
  // and also style the disabled state subtly.
  const buttonSx = {
    borderColor: isDark ? theme.palette.text.primary : undefined,
    color: isDark ? theme.palette.text.primary : undefined,
    "&:hover": {
      borderColor: isDark ? theme.palette.primary.main : undefined,
    },
    "&.Mui-disabled": {
      opacity: 0.6,
      borderColor: isDark ? theme.palette.text.secondary : undefined,
      color: isDark ? theme.palette.text.secondary : undefined,
    },
  };

  // Styling for the TextField outlined input when in dark mode.
  const textFieldSx = {
    width: "60px",
    "& .MuiOutlinedInput-root": {
      "& fieldset": {
        borderColor: isDark ? theme.palette.text.primary : undefined,
      },
      "&:hover fieldset": {
        borderColor: isDark ? theme.palette.primary.main : undefined,
      },
      "&.Mui-focused fieldset": {
        borderColor: isDark ? theme.palette.primary.main : undefined,
      },
    },
    // Custom styles to remove the increment and decrement arrows
    "& input[type=number]::-webkit-outer-spin-button, & input[type=number]::-webkit-inner-spin-button": {
      display: "none",
    },
    "& input[type=number]": {
      "-moz-appearance": "textfield", // Firefox
    },
  };

  return (
    <Box display="flex" alignItems="center" justifyContent="center" gap={2}>
      <Button
        variant="outlined"
        onClick={() => handlePageChange("prev")}
        disabled={currentPage === 1}
        aria-label="Go to Previous Page"
        sx={buttonSx}
      >
        Previous
      </Button>
      <Box display="flex" alignItems="center" gap={1}>
        <Typography sx={{ color: isDark ? theme.palette.text.primary : undefined }}>
          Page
        </Typography>
        <TextField
          id="page-input"
          type="number"
          value={currentPage}
          onChange={handleCustomPageChange}
          inputProps={{ min: 1, max: totalPages }}
          aria-label="Enter a page number"
          size="small"
          sx={textFieldSx}
        />
        <Typography sx={{ color: isDark ? theme.palette.text.primary : undefined }}>
          of {totalPages}
        </Typography>
      </Box>
      <Button
        variant="outlined"
        onClick={() => handlePageChange("next")}
        disabled={currentPage === totalPages}
        aria-label="Go to Next Page"
        sx={buttonSx}
      >
        Next
      </Button>
    </Box>
  );
};

Pagination.propTypes = {
  totalItems: PropTypes.number.isRequired,
  itemsPerPage: PropTypes.number.isRequired,
  currentPage: PropTypes.number.isRequired,
  onPageChange: PropTypes.func.isRequired,
};

export default Pagination;
