import React, { useState, useEffect, useMemo } from "react";
import {
  Box,
  Card,
  CardContent,
  Typography,
  Grid,
  alpha,
  useTheme,
  CircularProgress,
  Divider,
  Tooltip,
  LinearProgress
} from "@mui/material";
import WhatshotIcon from "@mui/icons-material/Whatshot";
import { ACTIVITY_QUERY, WEEKLY_ACTIVITY_QUERY, fetchFromAniList } from "../../../../queries/queries";
import MovieIcon from "@mui/icons-material/Movie";
import MenuBookIcon from "@mui/icons-material/MenuBook";

/**
 * Most Consumed component that shows the most watched/read anime/manga for a given period
 * Inspired by Last.fm's most listened section
 */
const MostConsumed = ({ userId, mediaType, paperStyles, formatTime }) => {
  const theme = useTheme();
  const [mostConsumedData, setMostConsumedData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  
  // Get the previous week's date range (Monday to Sunday)
  const getPreviousWeekRange = useMemo(() => {
    const now = new Date();
    const lastMonday = new Date(now);
    lastMonday.setDate(now.getDate() - now.getDay() - 6);
    const lastSunday = new Date(lastMonday);
    lastSunday.setDate(lastMonday.getDate() + 6);
    
    return {
      start: Math.floor(lastMonday.getTime() / 1000),
      end: Math.floor(lastSunday.getTime() / 1000)
    };
  }, []);

  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        setError(null);

        const response = await fetchFromAniList(ACTIVITY_QUERY, {
          userId: parseInt(userId),
          type: mediaType.toUpperCase(),
          perPage: 100
        });

        if (!response?.Page?.activities) {
          setMostConsumedData({ hasActivity: false });
          return;
        }

        const activities = response.Page.activities;
        const mediaMap = new Map();

        activities.forEach(activity => {
          if (!activity.media) return;

          const mediaId = activity.media.id;
          const progress = activity.progress || 1;

          if (!mediaMap.has(mediaId)) {
            mediaMap.set(mediaId, {
              id: mediaId,
              title: activity.media.title.userPreferred,
              coverImage: activity.media.coverImage,
              format: activity.media.format,
              count: 0,
              minutesWatched: 0,
              genres: activity.media.genres || [],
              progress: 0
            });
          }

          const media = mediaMap.get(mediaId);
          media.count += progress;
          media.progress = Math.max(media.progress, activity.progress);

          if (mediaType === "anime" && activity.media.duration) {
            media.minutesWatched += progress * activity.media.duration;
          }
        });

        const mostConsumedItems = Array.from(mediaMap.values())
          .sort((a, b) => b.count - a.count)
          .slice(0, 5);

        setMostConsumedData({
          hasActivity: mostConsumedItems.length > 0,
          mostConsumedItems,
          totalCount: mostConsumedItems.reduce((sum, item) => sum + item.count, 0)
        });

      } catch (err) {
        console.error("Error fetching most consumed data:", err);
        setError(err.message);
        setMostConsumedData({ hasActivity: false });
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [userId, mediaType]);
  
  if (loading) {
    return (
      <Card sx={{ ...paperStyles, mb: 3 }}>
        <CardContent sx={{ textAlign: 'center', py: 5 }}>
          <CircularProgress size={40} />
          <Typography variant="body2" sx={{ mt: 2 }}>
            Finding your most consumed {mediaType}...
          </Typography>
        </CardContent>
      </Card>
    );
  }
  
  if (error) {
    return (
      <Card sx={{ ...paperStyles, mb: 3 }}>
        <CardContent>
          <Typography variant="h6" color="error">
            Couldn't load most consumed data
          </Typography>
          <Typography variant="body2">{error}</Typography>
        </CardContent>
      </Card>
    );
  }
  
  if (!mostConsumedData) {
    return (
      <Card sx={{ ...paperStyles, mb: 3 }}>
        <CardContent>
          <Typography variant="h6">No consumption data available</Typography>
          <Typography variant="body2">
            We don't have any data about your most consumed {mediaType}.
          </Typography>
        </CardContent>
      </Card>
    );
  }
  
  // Handle no activity case
  if (!mostConsumedData.hasActivity) {
    return (
      <Card sx={{ ...paperStyles, mb: 3 }}>
        <CardContent>
          <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
            <WhatshotIcon sx={{ color: theme.palette.error.main, mr: 1 }} />
            <Typography variant="h6" sx={{ fontWeight: 600 }}>
              Top {mediaType === "anime" ? "Watched" : "Read"} This Week
            </Typography>
          </Box>
          
          <Box sx={{ 
            py: 4, 
            display: 'flex', 
            flexDirection: 'column', 
            alignItems: 'center',
            justifyContent: 'center' 
          }}>
            <Box sx={{ 
              width: 60, 
              height: 60, 
              borderRadius: '50%', 
              backgroundColor: alpha(theme.palette.text.secondary, 0.1),
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              mb: 2
            }}>
              <WhatshotIcon color="action" sx={{ fontSize: 30 }} />
            </Box>
            <Typography variant="h6" color="text.secondary">
              No activity during this week
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mt: 1, maxWidth: 400, textAlign: 'center' }}>
              You didn't {mediaType === "anime" ? "watch any anime" : "read any manga"} this week.
            </Typography>
          </Box>
        </CardContent>
      </Card>
    );
  }
  
  // Calculate maximum count for normalization
  const maxCount = Math.max(...mostConsumedData.mostConsumedItems.map(item => item.count));
  
  return (
    <Card 
      sx={{ 
        ...paperStyles, 
        mb: 3,
        overflow: 'hidden'
      }}
    >
      <CardContent>
        <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
          <WhatshotIcon sx={{ color: theme.palette.error.main, mr: 1 }} />
          <Typography variant="h6" sx={{ fontWeight: 600 }}>
            Top {mediaType === "anime" ? "Watched" : "Read"} This Week
          </Typography>
        </Box>
        
        <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
          You {mediaType === "anime" ? "watched" : "read"} {mostConsumedData.totalCount} {mediaType === "anime" ? "episodes" : "chapters"} this week
        </Typography>
        
        {mostConsumedData.mostConsumedItems.map((item, index) => (
          <Box key={item.id} sx={{ mb: index < mostConsumedData.mostConsumedItems.length - 1 ? 2 : 0 }}>
            <Grid container spacing={2} alignItems="center">
              {/* Rank */}
              <Grid item xs={1}>
                <Typography 
                  variant="body1" 
                  sx={{ 
                    fontWeight: 'bold',
                    color: index === 0 
                      ? theme.palette.error.main 
                      : index === 1 
                        ? theme.palette.warning.main 
                        : index === 2 
                          ? theme.palette.info.main
                          : 'text.secondary'
                  }}
                >
                  {index + 1}
                </Typography>
              </Grid>
              
              {/* Image */}
              <Grid item xs={2} sm={1}>
                <Box 
                  sx={{ 
                    borderRadius: 1,
                    overflow: 'hidden',
                    width: '100%',
                    paddingTop: '140%',
                    position: 'relative',
                    backgroundColor: alpha(theme.palette.primary.main, 0.1),
                    boxShadow: '0 2px 8px rgba(0,0,0,0.1)'
                  }}
                >
                  {item.coverImage && item.coverImage.medium ? (
                    <Box
                      component="img"
                      src={item.coverImage.medium}
                      alt={item.title}
                      sx={{
                        position: 'absolute',
                        top: 0,
                        left: 0,
                        width: '100%',
                        height: '100%',
                        objectFit: 'cover'
                      }}
                    />
                  ) : (
                    <Box
                      sx={{
                        position: 'absolute',
                        top: 0,
                        left: 0,
                        width: '100%',
                        height: '100%',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        backgroundColor: alpha(theme.palette.text.secondary, 0.1),
                        color: theme.palette.text.secondary
                      }}
                    >
                      {mediaType === "anime" ? <MovieIcon /> : <MenuBookIcon />}
                    </Box>
                  )}
                </Box>
              </Grid>
              
              {/* Details */}
              <Grid item xs={9} sm={7}>
                <Tooltip title={item.title}>
                  <Typography 
                    variant="subtitle2" 
                    sx={{ 
                      fontWeight: 'bold',
                      overflow: 'hidden',
                      textOverflow: 'ellipsis',
                      display: '-webkit-box',
                      WebkitLineClamp: 1,
                      WebkitBoxOrient: 'vertical'
                    }}
                  >
                    {item.title}
                  </Typography>
                </Tooltip>
                
                <Box sx={{ display: 'flex', alignItems: 'center' }}>
                  <Typography 
                    variant="caption" 
                    color="text.secondary"
                    sx={{ mr: 1 }}
                  >
                    {item.format || "Unknown"}
                  </Typography>
                  
                  {item.genres && item.genres.slice(0, 2).map((genre, i) => (
                    <Typography 
                      key={genre}
                      variant="caption" 
                      sx={{ 
                        px: 0.8,
                        py: 0.2,
                        borderRadius: 10,
                        backgroundColor: alpha(i === 0 ? theme.palette.primary.main : theme.palette.secondary.main, 0.1),
                        color: i === 0 ? theme.palette.primary.main : theme.palette.secondary.main,
                        fontSize: '0.65rem',
                        fontWeight: 'medium',
                        mr: 0.5
                      }}
                    >
                      {genre}
                    </Typography>
                  ))}
                </Box>
              </Grid>
              
              {/* Count */}
              <Grid item xs={12} sm={3}>
                <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'flex-end' }}>
                  <Typography 
                    variant="body2" 
                    sx={{ 
                      fontWeight: 'bold',
                      color: theme.palette.primary.main
                    }}
                  >
                    {item.count}
                  </Typography>
                  <Typography 
                    variant="caption" 
                    color="text.secondary"
                    sx={{ ml: 0.5 }}
                  >
                    {mediaType === "anime" ? "eps" : "ch"}
                  </Typography>
                </Box>
                
                <Tooltip 
                  title={
                    <React.Fragment>
                      <Typography variant="subtitle2" sx={{ fontWeight: 'bold', mb: 0.5 }}>
                        {item.title}
                      </Typography>
                      <Typography variant="body2">
                        {mediaType === "anime" 
                          ? `${formatTime(item.minutesWatched)} watched this week (${item.progress} episodes total)`
                          : `${item.count} chapters read this week (${item.progress} chapters total)`
                        }
                      </Typography>
                      {item.genres && item.genres.length > 0 && (
                        <Typography variant="body2" sx={{ mt: 0.5 }}>
                          Genres: {item.genres.join(', ')}
                        </Typography>
                      )}
                    </React.Fragment>
                  }
                >
                  <LinearProgress 
                    variant="determinate" 
                    value={(item.count / maxCount) * 100} 
                    sx={{ 
                      height: 4,
                      mt: 0.5,
                      borderRadius: 2,
                      backgroundColor: alpha(theme.palette.primary.main, 0.1),
                      '& .MuiLinearProgress-bar': {
                        backgroundColor: index === 0 
                          ? theme.palette.error.main 
                          : index === 1 
                            ? theme.palette.warning.main 
                            : theme.palette.primary.main
                      }
                    }} 
                  />
                </Tooltip>
              </Grid>
            </Grid>
            
            {index < mostConsumedData.mostConsumedItems.length - 1 && (
              <Divider sx={{ my: 1.5 }} />
            )}
          </Box>
        ))}
      </CardContent>
    </Card>
  );
};

export default MostConsumed;
