import React, { useEffect, useState, useMemo, useCallback } from "react";
import { Box, Typography, Divider, Tooltip } from "@mui/material";
import { useTheme, alpha, keyframes } from "@mui/material/styles";
import { ACTIVITY_HISTORY_QUERY, USER_QUERY_BY_NAME, fetchFromAniList } from "../queries/queries";

// Default username if none is provided
const DEFAULT_USERNAME = "ajisai";

const ActivityHistory = ({ userId, username }) => {
  const theme = useTheme();
  const [activityMap, setActivityMap] = useState({});
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [lastUpdated, setLastUpdated] = useState(null);
  const [resolvedUserId, setResolvedUserId] = useState(userId);

  // Set the timespan (90 days here)
  const daysSpan = 90;
  const cutoffTimestamp = Math.floor(
    (Date.now() - (daysSpan - 1) * 24 * 60 * 60 * 1000) / 1000
  );

  // Calculate the maximum activity count for better color scaling
  const maxActivityCount = useMemo(() => {
    if (Object.keys(activityMap).length === 0) return 1;
    return Math.max(...Object.values(activityMap), 1);
  }, [activityMap]);

  // Resolve username to userId if needed
  useEffect(() => {
    const resolveUser = async () => {
      // If userId is already provided, use it
      if (userId) {
        console.log(`Using provided userId: ${userId}`);
        setResolvedUserId(userId);
        return;
      }

      // Use provided username or default
      const userToFetch = username || DEFAULT_USERNAME;
      console.log(`Resolving username: ${userToFetch}`);
      
      try {
        // Check if we have a cached userId for this username
        const cachedUserId = localStorage.getItem(`userId-${userToFetch}`);
        if (cachedUserId) {
          console.log(`Using cached userId for ${userToFetch}: ${cachedUserId}`);
          setResolvedUserId(parseInt(cachedUserId, 10));
          return;
        }

        // Fetch userId from username
        console.log(`Fetching userId for username: ${userToFetch}`);
        const userData = await fetchFromAniList(USER_QUERY_BY_NAME, {
          username: userToFetch
        });

        if (!userData || !userData.User || !userData.User.id) {
          throw new Error(`Could not resolve user ID for username: ${userToFetch}`);
        }

        const fetchedUserId = userData.User.id;
        console.log(`Resolved username ${userToFetch} to userId: ${fetchedUserId}`);
        setResolvedUserId(fetchedUserId);
        
        // Cache the userId for future use
        localStorage.setItem(`userId-${userToFetch}`, fetchedUserId.toString());
      } catch (error) {
        console.error("Error resolving user ID:", error);
        setError(`Could not resolve user: ${error.message}`);
        setLoading(false);
      }
    };

    resolveUser();
  }, [userId, username]);

  const fetchActivities = useCallback(async () => {
    if (!resolvedUserId) {
      // Skip fetching if we don't have a userId yet
      return;
    }

    let currentPage = 1;
    let hasNextPage = true;
    const newActivityMap = {};
    let retryCount = 0;
    const MAX_RETRIES = 3;
    const MAX_PAGES = 15; // Increased from 10 to 15 to accommodate more days

    try {
      while (hasNextPage && currentPage <= MAX_PAGES) {
        try {
          // Respect rate limits with a delay
          if (currentPage > 1) {
            await new Promise((resolve) => setTimeout(resolve, 1000));
          }

          console.log(`Fetching activities for user ${resolvedUserId}, page ${currentPage}`);
          const data = await fetchFromAniList(ACTIVITY_HISTORY_QUERY, {
            userId: resolvedUserId,
            page: currentPage,
          });

          if (!data || !data.Page) {
            console.error("Invalid response format:", data);
            throw new Error("Invalid response format from AniList API");
          }

          const pageActivities = data.Page.activities || [];
          if (!pageActivities.length) {
            console.log("No activities found on this page");
            break;
          }

          console.log(`Found ${pageActivities.length} activities on page ${currentPage}`);
          let shouldBreak = false;
          for (const activity of pageActivities) {
            if (activity && activity.createdAt && activity.createdAt >= cutoffTimestamp) {
              const dateString = new Date(activity.createdAt * 1000)
                .toISOString()
                .split("T")[0];
              newActivityMap[dateString] = (newActivityMap[dateString] || 0) + 1;
            } else if (activity && activity.createdAt) {
              shouldBreak = true;
              break;
            }
          }

          const lastActivity = pageActivities[pageActivities.length - 1];
          if (shouldBreak || (lastActivity && lastActivity.createdAt < cutoffTimestamp)) {
            hasNextPage = false;
          } else {
            hasNextPage = data.Page.pageInfo && data.Page.pageInfo.hasNextPage;
            currentPage++;
          }
          
          // Reset retry count on successful request
          retryCount = 0;
        } catch (err) {
          console.error(`Error on page ${currentPage}:`, err);
          retryCount++;
          if (retryCount >= MAX_RETRIES) {
            throw new Error(`Failed after ${MAX_RETRIES} retries: ${err.message}`);
          }
          // Exponential backoff
          const delay = Math.pow(2, retryCount) * 1000;
          console.log(`Retrying in ${delay}ms... (attempt ${retryCount}/${MAX_RETRIES})`);
          await new Promise((resolve) => 
            setTimeout(resolve, delay)
          );
        }
      }

      console.log(`Finished fetching activities, found data for ${Object.keys(newActivityMap).length} days`);
      
      // Store the data with timestamp
      const timestamp = Date.now();
      const cacheData = { 
        activityMap: newActivityMap, 
        timestamp,
        userId: resolvedUserId 
      };
      
      localStorage.setItem(`activityMap-${resolvedUserId}`, JSON.stringify(cacheData));
      setActivityMap(newActivityMap);
      setLastUpdated(timestamp);
      setLoading(false);
    } catch (error) {
      console.error("Error fetching activities:", error);
      setError(error.message);
      setLoading(false);
    }
  }, [resolvedUserId, cutoffTimestamp]);

  useEffect(() => {
    if (!resolvedUserId) return;
    
    setLoading(true);
    setError(null);
    
    const storedDataString = localStorage.getItem(`activityMap-${resolvedUserId}`);
    
    if (storedDataString) {
      try {
        const storedData = JSON.parse(storedDataString);
        
        // Check if the cached data is for the current user and not too old (24 hours)
        // Also check if it covers the full 90-day span
        const isValid = 
          storedData.userId === resolvedUserId && 
          storedData.timestamp && 
          Date.now() - storedData.timestamp < 24 * 60 * 60 * 1000;
        
        if (isValid) {
          setActivityMap(storedData.activityMap);
          setLastUpdated(storedData.timestamp);
          setLoading(false);
          return;
        }
      } catch (error) {
        console.error("Error parsing stored activity data:", error);
        // Continue to fetch fresh data
      }
    }
    
    fetchActivities();
  }, [fetchActivities, resolvedUserId]);

  // Define a subtle fade & scale animation for grid cells
  const fadeIn = keyframes`
    from {
      opacity: 0;
      transform: scale(0.8);
    }
    to {
      opacity: 1;
      transform: scale(1);
    }
  `;

  const grid = useMemo(() => {
    const today = new Date();
    const startDate = new Date(today);
    startDate.setDate(today.getDate() - (daysSpan - 1));
    const gridItems = [];
    let index = 0;
    const currentDate = new Date(startDate);
    const endDate = new Date(today);

    // Create a 3x30 grid (3 rows, 30 columns = 90 days)
    const rows = 3; // 3 rows
    const cols = 30; // 30 columns
    
    // Fill the grid with empty cells first
    const gridCells = Array(rows * cols).fill(null);
    
    // Populate the grid with actual data
    while (currentDate <= endDate) {
      const dateString = currentDate.toISOString().split("T")[0];
      const activityCount = activityMap[dateString] || 0;
      
      // Calculate position in the grid - fill from left to right, top to bottom
      const position = index;
      
      if (position < gridCells.length) {
        gridCells[position] = {
          date: new Date(currentDate),
          dateString,
          activityCount
        };
      }
      
      index++;
      currentDate.setDate(currentDate.getDate() + 1);
    }
    
    // Convert grid cells to React components
    return gridCells.map((cell, idx) => {
      if (!cell) return (
        <Box
          key={`empty-${idx}`}
          sx={{
            width: { xs: "0.7rem", sm: "0.8rem", md: "0.9rem" },
            height: { xs: "0.7rem", sm: "0.8rem", md: "0.9rem" },
            borderRadius: "0.2rem",
            backgroundColor: theme.palette.grey[200],
          }}
        />
      );
      
      const { date, dateString, activityCount } = cell;
      const formattedDate = date.toLocaleDateString(undefined, {
        weekday: 'short',
        year: 'numeric',
        month: 'short',
        day: 'numeric'
      });
      
      // Calculate intensity based on activity count relative to max
      const intensity = activityCount > 0 
        ? Math.max(0.2, Math.min(activityCount / (maxActivityCount * 0.7), 1))
        : 0;
      
      return (
        <Tooltip 
          key={dateString} 
          title={`${formattedDate}: ${activityCount} activities`}
          arrow
        >
          <Box
            sx={{
              width: { xs: "0.7rem", sm: "0.8rem", md: "0.9rem" },
              height: { xs: "0.7rem", sm: "0.8rem", md: "0.9rem" },
              borderRadius: "0.2rem",
              backgroundColor: activityCount > 0
                ? alpha(theme.palette.primary.main, intensity)
                : theme.palette.grey[300],
              animation: `${fadeIn} 0.3s ease-out ${idx * 0.01}s forwards`,
              transition: "transform 0.2s, box-shadow 0.2s",
              "&:hover": {
                transform: "scale(1.2)",
                boxShadow: `0 0 5px ${alpha(theme.palette.primary.main, 0.5)}`,
                cursor: "pointer"
              }
            }}
          />
        </Tooltip>
      );
    });
  }, [activityMap, theme, daysSpan, fadeIn, maxActivityCount]);

  return (
    <Box sx={{ px: 2, py: 1 }}>
      {loading ? (
        <Box sx={{ textAlign: "center", py: 4 }}>
          <Typography variant="body2" color="text.secondary">
            Loading activity history...
          </Typography>
        </Box>
      ) : error ? (
        <Box sx={{ textAlign: "center", py: 4 }}>
          <Typography variant="body2" color="error">
            Error loading activity history: {error}
          </Typography>
        </Box>
      ) : (
        <>
          <Box
            sx={{
              p: 0.5,
              display: "grid",
              gridTemplateRows: "repeat(3, 1fr)",
              gridTemplateColumns: "repeat(30, 1fr)",
              gap: { xs: 0.2, sm: 0.25, md: 0.3 },
              justifyItems: "center",
              width: "100%",
              maxWidth: "100%",
              overflow: "hidden",
              mb: 1
            }}
          >
            {grid}
          </Box>
          
          <Box sx={{ 
            display: "flex", 
            justifyContent: "space-between", 
            alignItems: "center",
            mt: 1,
            px: 0.5
          }}>
            <Box sx={{ 
              display: "flex", 
              alignItems: "center", 
              gap: 1,
              fontSize: "0.7rem"
            }}>
              <Box sx={{ 
                display: "flex", 
                alignItems: "center", 
                gap: 0.5 
              }}>
                <Box sx={{ 
                  width: "0.7rem", 
                  height: "0.7rem", 
                  borderRadius: "0.2rem",
                  backgroundColor: alpha(theme.palette.primary.main, 0.2)
                }} />
                <Typography variant="caption" color="text.secondary">Less</Typography>
              </Box>
              <Box sx={{ 
                display: "flex", 
                alignItems: "center", 
                gap: 0.5 
              }}>
                <Box sx={{ 
                  width: "0.7rem", 
                  height: "0.7rem", 
                  borderRadius: "0.2rem",
                  backgroundColor: alpha(theme.palette.primary.main, 0.8)
                }} />
                <Typography variant="caption" color="text.secondary">More</Typography>
              </Box>
            </Box>
            
            <Typography 
              variant="caption" 
              color="text.secondary"
              sx={{ fontSize: "0.7rem" }}
            >
              {lastUpdated ? 
                `Last updated: ${new Date(lastUpdated).toLocaleString()}` : 
                `Showing ${daysSpan} days of activity`
              }
            </Typography>
          </Box>
        </>
      )}
    </Box>
  );
};

export default ActivityHistory;