import React, { useMemo } from "react";
import {
  Box,
  Card,
  CardContent,
  Typography,
  Divider,
  Grid,
  alpha,
  useTheme,
  Tooltip,
  LinearProgress
} from "@mui/material";
import AutoGraphIcon from "@mui/icons-material/AutoGraph";
import LocalFireDepartmentIcon from "@mui/icons-material/LocalFireDepartment";
import ScheduleIcon from "@mui/icons-material/Schedule";
import TrendingUpIcon from "@mui/icons-material/TrendingUp";
import EmojiEventsIcon from "@mui/icons-material/EmojiEvents";

/**
 * Quick Facts component that displays interesting statistics about the user's anime/manga habits
 * Inspired by Last.fm's statistics
 */
const QuickFacts = ({ stats, mediaType, paperStyles, formatTime }) => {
  const theme = useTheme();
  
  // Generate facts based on user's statistics
  const facts = useMemo(() => {
    if (!stats || !stats[mediaType]) return [];
    
    const currentStats = stats[mediaType];
    const facts = [];
    
    // Calculate average consumption per day
    const minutesPerDay = currentStats.minutesWatched 
      ? Math.round(currentStats.minutesWatched / 365) 
      : null;
      
    const chaptersPerDay = currentStats.chaptersRead 
      ? Math.round(currentStats.chaptersRead / 365 * 10) / 10
      : null;
    
    // Calculate average rating
    const avgScore = currentStats.meanScore 
      ? currentStats.meanScore.toFixed(1) 
      : null;
    
    // Get top 8 genres
    const topGenres = currentStats.genres 
      ? [...currentStats.genres].sort((a, b) => b.count - a.count).slice(0, 8)
      : [];
    
    // Get most watched year
    const releaseYears = currentStats.releaseYears 
      ? [...currentStats.releaseYears].sort((a, b) => b.count - a.count)
      : [];
    
    const mostWatchedYear = releaseYears[0] || null;
    
    // Calculate completion rate
    const completed = currentStats.statuses?.find(s => s.status === "COMPLETED")?.count || 0;
    const total = currentStats.count || 0;
    const completionRate = total ? Math.round((completed / total) * 100) : 0;
    
    // Media-specific facts
    if (mediaType === "anime") {
      if (minutesPerDay !== null) {
        facts.push({
          icon: <ScheduleIcon />,
          color: theme.palette.info.main,
          title: "Daily Anime",
          value: `${minutesPerDay} min`,
          description: `Based on your total watch time, you average ${minutesPerDay} minutes of anime per day`
        });
      }
      
      if (currentStats.episodesWatched) {
        const seriesCompleted = Math.round(currentStats.episodesWatched / 12);
        facts.push({
          icon: <AutoGraphIcon />,
          color: theme.palette.success.main,
          title: "Series Completed",
          value: `${seriesCompleted}`,
          description: `You've watched enough episodes to complete ${seriesCompleted} average anime series (12 episodes each)`
        });
      }
    } else {
      // Only add daily reading if it's not simulated data
      if (chaptersPerDay !== null && currentStats.chaptersRead > 0) {
        facts.push({
          icon: <ScheduleIcon />,
          color: theme.palette.info.main,
          title: "Daily Reading",
          value: `${chaptersPerDay} ch`,
          description: `Based on your total chapters read, you average ${chaptersPerDay} chapters per day`
        });
      }
      
      if (currentStats.volumesRead) {
        facts.push({
          icon: <AutoGraphIcon />,
          color: theme.palette.success.main,
          title: "Volumes Read",
          value: `${currentStats.volumesRead}`,
          description: `You've read ${currentStats.volumesRead} volumes of manga`
        });
      }
    }
    
    // General facts
    if (avgScore) {
      facts.push({
        icon: <EmojiEventsIcon />,
        color: theme.palette.warning.main,
        title: "Average Rating",
        value: `${avgScore}/10`,
        description: `Your average rating across all ${mediaType} entries`
      });
    }
    
    // Genre facts
    if (topGenres.length > 0) {
      const genreList = topGenres.map(g => g.genre).join(', ');
      facts.push({
        icon: <LocalFireDepartmentIcon />,
        color: theme.palette.secondary.main,
        title: "Top Genres",
        value: `${topGenres[0].genre}`,
        description: `Your most consumed genres: ${genreList}`,
        genres: topGenres
      });
    }
    
    // Era preference
    if (mostWatchedYear) {
      facts.push({
        icon: <TrendingUpIcon />,
        color: theme.palette.error.main,
        title: "Favorite Year",
        value: `${mostWatchedYear.releaseYear}`,
        description: `You've consumed the most ${mediaType} from ${mostWatchedYear.releaseYear}`
      });
    }
    
    // Completion rate
    facts.push({
      icon: <AutoGraphIcon />,
      color: theme.palette.primary.main,
      title: "Completion Rate",
      value: `${completionRate}%`,
      progressValue: completionRate,
      description: `You finish ${completionRate}% of the ${mediaType} you start`
    });
    
    return facts;
  }, [stats, mediaType, theme, formatTime]);
  
  if (!stats || !stats[mediaType] || facts.length === 0) {
    return (
      <Card sx={{ ...paperStyles, mb: 3 }}>
        <CardContent>
          <Typography variant="h6">Quick Facts</Typography>
          <Typography variant="body2" color="text.secondary">
            Not enough data to generate interesting facts.
          </Typography>
        </CardContent>
      </Card>
    );
  }
  
  return (
    <Card sx={{ ...paperStyles, mb: 3 }}>
      <CardContent sx={{ pb: 1 }}>
        <Typography variant="h6" sx={{ fontWeight: 600, mb: 0.5 }}>
          Quick Facts
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
          Insights about your {mediaType} habits
        </Typography>
        
        <Grid container spacing={2}>
          {facts.map((fact, index) => (
            <Grid item xs={12} sm={6} md={4} key={fact.title}>
              <Tooltip title={fact.description} arrow>
                <Box 
                  sx={{ 
                    p: 1.5, 
                    borderRadius: 2,
                    border: `1px solid ${alpha(fact.color, 0.3)}`,
                    backgroundColor: alpha(fact.color, 0.05),
                    height: '100%',
                    '&:hover': {
                      backgroundColor: alpha(fact.color, 0.1)
                    }
                  }}
                >
                  <Box sx={{ display: 'flex', alignItems: 'center', mb: 0.5 }}>
                    <Box 
                      sx={{ 
                        color: fact.color,
                        mr: 1,
                        display: 'flex',
                        alignItems: 'center',
                        fontSize: '0.9rem'
                      }}
                    >
                      {fact.icon}
                    </Box>
                    <Typography variant="caption" color="text.secondary" sx={{ fontWeight: 500 }}>
                      {fact.title}
                    </Typography>
                  </Box>
                  
                  <Typography variant="h6" sx={{ fontWeight: 'bold', mb: 0.5, color: fact.color }}>
                    {fact.value}
                  </Typography>
                  
                  {fact.genres && (
                    <Typography variant="caption" color="text.secondary">
                      {fact.genres.slice(0, 3).map(g => g.genre).join(', ')}
                      {fact.genres.length > 3 && ` +${fact.genres.length - 3}`}
                    </Typography>
                  )}
                  
                  {fact.progressValue && (
                    <LinearProgress 
                      variant="determinate" 
                      value={fact.progressValue} 
                      sx={{ 
                        height: 4, 
                        borderRadius: 3,
                        backgroundColor: alpha(fact.color, 0.2),
                        '& .MuiLinearProgress-bar': {
                          backgroundColor: fact.color
                        }
                      }} 
                    />
                  )}
                </Box>
              </Tooltip>
            </Grid>
          ))}
        </Grid>
      </CardContent>
    </Card>
  );
};

export default QuickFacts;
