import { Navigate } from 'react-router-dom';
import AnimeStatistics from './pages/userpage/statistics/animeStatistics';
import MangaStatistics from './pages/userpage/statistics/mangaStatistics';
import Landing from './pages/landingPage';
import Userpage from './pages/userPage';
import AniListComponent from './components/AniListComponent';

export const routes = [
  {
    path: '/',
    element: <Landing />,
  },
  {
    path: '/anilist',
    element: <AniListComponent />,
  },
  {
    path: '/user',
    element: <Userpage />,
    children: [
      {
        path: 'statistics/anime',
        element: <AnimeStatistics />,
      },
      {
        path: 'statistics/manga',
        element: <MangaStatistics />,
      },
      {
        path: 'overview',
        element: <AnimeStatistics />,
      },
      {
        path: '',
        element: <Navigate to="statistics/anime" replace />,
      },
    ],
  },
  {
    path: '*',
    element: <Navigate to="/" replace />,
  },
]; 