import React, { useState } from "react";
import {
  Box,
  Paper,
  Typography,
  useTheme,
  Divider,
  Container,
  Fade,
  Skeleton,
  alpha,
  Grid,
} from "@mui/material";
import ActivityDisplay from "../../components/activityDisplay.jsx";
import FavoritesDisplay from "../../components/favoritesDisplay.jsx";
import ActivityHistory from "../../components/activityHistory.jsx";
import SectionNav from "../../components/userpage/sectionNav.jsx";

/**
 * Overview component that displays user activity and favorites
 * 
 * @param {Object} userData - User information including favorites
 * @param {Array} activities - User activity data
 * @param {String} userId - User ID
 */
const Overview = ({ userData, activities, userId }) => {
  const theme = useTheme();
  const isLoading = !userData || !activities;
  const [activeSection, setActiveSection] = useState("");
  
  // Shared paper styles to maintain consistency
  const paperStyles = {
    p: 3,
    borderRadius: 2,
    border: `1px solid ${alpha(theme.palette.divider, 0.1)}`,
    background: alpha(theme.palette.background.paper, 0.8),
    backdropFilter: "blur(8px)",
    transition: "all 0.3s ease",
  };

  // Skeleton loading styles
  const skeletonStyles = {
    borderRadius: 1,
    backgroundColor: alpha(theme.palette.text.primary, 0.05),
  };

  // Define sections for the SectionNav
  const sections = [
    { 
      id: "activitySection", 
      label: "Recent Activity",
      color: theme.palette.primary.main,
      description: "Your recent activity feed"
    },
    { 
      id: "activityHistorySection", 
      label: "Activity History",
      color: theme.palette.info.main,
      description: "Your activity history over time"
    },
    { 
      id: "favoritesSection", 
      label: "Favorites",
      color: theme.palette.warning.main,
      description: "Your favorite content"
    },
  ];

  // Handle section change
  const handleSectionChange = (sectionId) => {
    setActiveSection(sectionId);
  };

  // Create skeleton grid for favorites loading state
  const FavoritesLoadingSkeleton = () => (
    <Grid container spacing={2}>
      {[...Array(10)].map((_, index) => (
        <Grid item xs={12} sm={6} md={2.4} key={index}>
          <Skeleton
            variant="rectangular"
            height={80}
            sx={skeletonStyles}
          />
        </Grid>
      ))}
    </Grid>
  );

  return (
    <Fade in={!isLoading} timeout={800}>
      <Box
        component="main"
        sx={{
          display: "flex",
          flexDirection: "column",
          gap: 3,
          width: "100%",
          mb: 4,
          px: { xs: 1, sm: 2 },
          py:2,
        }}
        aria-label="User overview"
      >
        {/* Section Navigation */}
        <SectionNav 
          sections={sections} 
          activeSection={activeSection} 
          onSectionChange={handleSectionChange} 
          title="Overview Sections"
        />

        {/* Activity Section */}
        <Paper
          aria-label="Activity feed container"
          elevation={0}
          sx={{
            ...paperStyles,
            position: "relative",
            overflow: "hidden",
            "&::before": {
              content: '""',
              position: "absolute",
              top: 0,
              left: 0,
              width: "100%",
              height: "4px",
              background: `linear-gradient(90deg, ${theme.palette.primary.main}, ${theme.palette.secondary.main})`,
            },
          }}
          id="activitySection"
        >
          <Typography 
            variant="h6" 
            color="primary" 
            sx={{ mb: 2, fontWeight: 600 }}
          >
            Recent Activity
          </Typography>
          <Divider sx={{ mb: 2 }} />
          
          {isLoading ? (
            <Box sx={{ pt: 1 }}>
              <Skeleton
                variant="rectangular"
                height={120}
                sx={{ ...skeletonStyles, mb: 1 }}
              />
              <Skeleton
                variant="rectangular"
                height={120}
                sx={skeletonStyles}
              />
            </Box>
          ) : (
            <ActivityDisplay activities={activities} />
          )}
        </Paper>

        <Paper
          elevation={0}
          sx={{
            ...paperStyles,
            position: "relative",
            overflow: "hidden",
            "&::before": {
              content: '""',
              position: "absolute",
              top: 0,
              left: 0,
              width: "100%",
              height: "4px",
              background: `linear-gradient(90deg, ${theme.palette.info.main}, ${theme.palette.success.main})`,
            },
          }}
          id="activityHistorySection"
        >
          <Typography
            variant="h6"
            color="primary"
            sx={{ mb: 2, fontWeight: 600 }}
          >
            Activity History
          </Typography>
          <Divider sx={{ mb: 2 }} />
          
          {isLoading ? (
            <Box sx={{ pt: 1 }}>
              <Skeleton
                variant="rectangular"
                height={120}
                sx={{ ...skeletonStyles, mb: 1 }}
              />
              <Skeleton
                variant="rectangular"
                height={120}
                sx={skeletonStyles}
              />
            </Box>
          ) : (
            <ActivityHistory userId={userId} username={userData?.name} />
          )}
        </Paper>

        {/* Favorites Section - 5x2 grid layout */}
        <Paper
          elevation={0}
          sx={{
            ...paperStyles,
            position: "relative",
            overflow: "hidden",
            "&::before": {
              content: '""',
              position: "absolute",
              top: 0,
              left: 0,
              width: "100%",
              height: "4px",
              background: `linear-gradient(90deg, ${theme.palette.warning.main}, ${theme.palette.error.main})`,
            },
          }}
          id="favoritesSection"
        >
          <Typography 
            variant="h6" 
            color="primary" 
            sx={{ mb: 2, fontWeight: 600 }}
          >
            Favorites
          </Typography>
          <Divider sx={{ mb: 2 }} />
          
          {isLoading ? (
            <FavoritesLoadingSkeleton />
          ) : (
            <Box sx={{ width: '100%' }}>
              {/* Pass grid configuration to FavoritesDisplay */}
              <FavoritesDisplay 
                favorites={userData.favourites} 
                gridConfig={{
                  container: {
                    spacing: 2,
                  },
                  item: {
                    xs: 12,     // Full width on extra small devices
                    sm: 6,      // 2 items per row on small devices
                    md: 2.4,    // 5 items per row on medium and up (5 × 2.4 = 12)
                  }
                }}
              />
            </Box>
          )}
        </Paper>
      </Box>
    </Fade>
  );
};

export default Overview;